const EXTENDED_EXPRESSIONS = {
    love: { label: "Yêu thương (Love)", desc: "dùng khi ký chủ nói lời ngọt ngào, tặng quà quý giá hoặc bày tỏ tình cảm chân thành." },
    wow: { label: "Kinh ngạc (Wow)", desc: "dùng khi ký chủ đạt thành tựu vượt bậc, đột phá cảnh giới khó tin hoặc có tình tiết cực kỳ bất ngờ xảy ra." },
    smug: { label: "Đắc ý (Smug)", desc: "dùng khi Hệ Thống tự phụ, kiêu ngạo, chứng minh mình đúng hoặc trêu chọc sự kém cỏi của ký chủ." },
    bashful: { label: "Ngượng ngùng (Bashful)", desc: "dùng khi Hệ Thống bối rối, đỏ mặt, ngượng ngùng trước các hành vi trêu ghẹo hoặc khen ngợi quá đà từ ký chủ." },
    pout: { label: "Hờn dỗi (Pout)", desc: "dùng khi Hệ Thống giận dỗi, không hài lòng nhẹ, muốn được ký chủ dỗ dành hoặc năn nỉ." },
    exhausted: { label: "Kiệt sức / Ngán ngẩm (Exhausted)", desc: "dùng khi năng lượng dâng hiến quá thấp (< 15) hoặc khi bất lực, bó tay trước những quyết định ngốc nghếch của ký chủ." },
    evil: { label: "Gian xảo / Ma mãnh (Evil)", desc: "dùng khi Hệ Thống nảy ra mưu đồ hắc ám, đề xuất các phương án tàn nhẫn hoặc muốn bày trò trừng phạt ký chủ." },
    speechless: { label: "Cạn lời (Speechless)", desc: "dùng khi ký chủ nói nhảm, có hành động quá ngớ ngẩn, điên rồ hoặc phi logic khiến Hệ Thống đứng hình." },
    sleepy: { label: "Ngái ngủ / Lười biếng (Sleepy)", desc: "dùng vào ban đêm, khi không gian tĩnh mịch hoặc khi Hệ Thống lười biếng, muốn đi ngủ và lười hỗ trợ." },
    scared: { label: "E sợ / Kiêng dè (Scared)", desc: "dùng khi cảm nhận được áp lực cực lớn từ thiên đạo, thực thể viễn cổ hùng mạnh hoặc u minh hắc ám rùng rợn xung quanh." }
};
const LoadGameAvatar = ({ game }) => {
    const [src, setSrc] = useState(null);
    useEffect(() => {
        const load = async () => {
            const cloudThumbnail = game.gameSettings?.playerAvatarThumbnail || game.playerAvatarThumbnail;
            if (cloudThumbnail) {
                setSrc(cloudThumbnail);
                return;
            }
            
            const playerChar = game.knowledge?.characters?.find(c => c.isPlayer || c.id === 'player');
            if (playerChar) {
                const extractedAvatar = playerChar.avatarUrl || playerChar.avatarBase64;
                if (extractedAvatar) {
                    setSrc(extractedAvatar);
                    return;
                }
            }

            if (game.id) {
                const cleanId = game.id.replace(/^(autosave_|manual_\d+_|github_\d+_)/, '');
                const cached = await getAvatarFromIndexedDB(`${cleanId}_player`);
                if (cached) {
                    setSrc(cached);
                }
            }
        };
        load();
    }, [game]);
    return (
        <div className="w-10 h-10 rounded-full border border-[#cda45e]/50 overflow-hidden flex-shrink-0 bg-[#0a0f0a] flex items-center justify-center mr-3 shadow-[0_0_10px_rgba(205,164,94,0.15)]">
            {src ? (
                <img src={src} className="w-full h-full object-cover" alt="Avatar" />
            ) : (
                <span className="text-xs text-[#cda45e]">👤</span>
            )}
        </div>
    );
};

const LoadGameModal = ({ savedGames, loadGame, setShowLoadGameModal, setConfirmationModal, userId, setModalMessage, db, appId, setSavedGames, cloudVipKey }) => (
    <div className="fixed inset-0 bg-black bg-opacity-80 flex items-center justify-center p-4 z-50 animate-fade-in">
      <div className="bg-[#162216] p-6 shadow-[0_0_50px_rgba(10,20,10,1)] w-full max-w-2xl max-h-[85vh] flex flex-col border border-[#cda45e]/50 relative">
        <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-[#cda45e] pointer-events-none"></div>
        <div className="absolute top-0 right-0 w-4 h-4 border-t-2 border-r-2 border-[#cda45e] pointer-events-none"></div>
        <div className="absolute bottom-0 left-0 w-4 h-4 border-b-2 border-l-2 border-[#cda45e] pointer-events-none"></div>
        <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-[#cda45e]/50 pointer-events-none"></div>

        <h2 className="text-2xl font-bold text-[#cda45e] mb-6 flex items-center uppercase tracking-widest border-b border-[#cda45e]/20 pb-4" style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>
            <ArrowPathIcon className="w-7 h-7 mr-3 text-[#cda45e]"/> Tải Game Đã Lưu
        </h2>
        
        {savedGames.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 text-[#8ba888]/60">
              <FolderOpenIcon className="w-16 h-16 mb-4 opacity-50 text-[#cda45e]"/>
              <p className="italic text-sm">Ngươi chưa có cuộc phiêu lưu nào được lưu lại.</p>
          </div>
        ) : (
          <div className="overflow-y-auto space-y-4 pr-2 scrollbar-thin scrollbar-thumb-[#cda45e] scrollbar-track-[#0a0f0a]">
            {savedGames.map(game => {
              let slotLabel = "Bản Lưu";
              let labelColor = "border-[#8ba888] text-[#8ba888] bg-[#8ba888]/10";
              
              if (game.isAutosave) {
                  slotLabel = "TỰ ĐỘNG LƯU (MÁY)";
                  labelColor = "border-[#cda45e] text-[#cda45e] bg-[#cda45e]/10";
              } else if (game.id && game.id.startsWith("manual_local_")) {
                  slotLabel = "LƯU TRÊN MÁY (THỦ CÔNG)";
                  labelColor = "border-[#8ba888] text-[#8ba888] bg-[#8ba888]/10";
              } else if (game.id && game.id.includes("manual_")) {
                  const slotNum = game.id.split('_')[1];
                  slotLabel = `NGỌC PHIẾN ${slotNum}`;
                  labelColor = "border-[#e8d3a1] text-[#e8d3a1] bg-[#e8d3a1]/10";
              } else if (game.isGithubCloud) {
                  slotLabel = `GITHUB PHIẾN ${game.githubSlot}`;
                  labelColor = "border-[#a78bfa] text-[#a78bfa] bg-[#a78bfa]/10";
              }

              return (
              <div key={game.id} className="bg-[#0a0f0a] p-4 border border-[#cda45e]/20 hover:border-[#cda45e]/60 transition-all shadow-[0_4px_10px_rgba(0,0,0,0.5)] group relative">
                <div className="absolute top-0 left-0 w-2 h-2 border-t border-l border-[#cda45e]/30 pointer-events-none"></div>
                <div className="absolute bottom-0 right-0 w-2 h-2 border-b border-r border-[#cda45e]/30 pointer-events-none"></div>

                <div className="flex justify-between items-center mb-3">
                    <span className={`text-[10px] font-bold px-2 py-0.5 border tracking-widest ${labelColor}`}>
                        {slotLabel}
                    </span>
                    <span className="text-[10px] text-[#8ba888] font-mono">
                        {game.updatedAt?.toDate ? new Date(game.updatedAt.toDate()).toLocaleString('vi-VN') : "N/A"}
                    </span>
                </div>

                <div className="flex justify-between items-center gap-4 mb-3 border-b border-[#cda45e]/10 pb-3">
                    <div className="text-[#e8d3a1] font-bold truncate flex items-center text-sm" style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>
                        <LoadGameAvatar game={game} />
                        {game.gameSettings?.characterName || "Vô Danh"}
                    </div>
                    <div className="text-[#cda45e] truncate flex items-center text-sm font-semibold max-w-[55%]" style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>
                        <span className="truncate">{game.gameSettings?.storyTitle || "Thế Giới Vô Danh"}</span>
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4 ml-2 flex-shrink-0"><path fillRule="evenodd" d="M9.69 18.933.003.001a9.7 9.7 0 0 1-2.92-1.928 9.7 9.7 0 0 1-2.226-3.111l-.001-.002A9.7 9.7 0 0 1 3 9.75c0-4.42 3.58-8 8-8s8 3.58 8 8a9.7 9.7 0 0 1-.547 3.142l-.001.002a9.7 9.7 0 0 1-2.226 3.111 9.7 9.7 0 0 1-2.92 1.928l-.003.001a.75.75 0 0 1-.74 0ZM8.5 9.75a2.25 2.25 0 1 0 4.5 0 2.25 2.25 0 0 0-4.5 0Z" clipRule="evenodd" /></svg>
                    </div>
                </div>

                <div className="flex justify-between items-center text-xs text-[#8ba888] mb-4">
                     <span>Độ khó: <span className="text-[#e8d3a1] font-semibold">{game.gameSettings?.difficulty || "Thường"}</span></span>
                     <span className="text-[#cda45e] font-mono">Lượt: {game.currentTurn || 0}</span>
                </div>

                <div className="flex space-x-3">
                    <button
                        onClick={() => loadGame(game)}
                        className="flex-1 bg-[#1b2a1b] border border-[#cda45e]/60 hover:bg-[#cda45e]/20 text-[#cda45e] hover:text-white font-bold py-2.5 px-4 rounded-sm text-xs shadow-[inset_0_0_10px_rgba(205,164,94,0.1)] transition-all uppercase tracking-widest flex items-center justify-center gap-2"
                    >
                        <PlayIcon className="w-4 h-4"/> Tiếp Tục
                    </button>
                    <button
                        onClick={() => {
                            setConfirmationModal({
                                show: true,
                                title: 'Xác Nhận Xóa',
                                content: `Bạn có chắc chắn muốn xóa bản lưu này không?`,
                                onConfirm: async () => {
                                    try {
                                        if (game.isAutosave || game.id.startsWith("manual_local_")) {
                                            await deleteIndexedDBKey(game.id);
                                            if (setSavedGames) {
                                                setSavedGames(prev => prev.filter(g => g.id !== game.id));
                                            }
                                        } else if (game.isGithubCloud && game.githubSlot) {
                                            const slotPath = `${GITHUB_SAVES_DIR}/slot_${game.githubSlot}.json`;
                                            const existingSlotFile = await getGithubJsonFile(slotPath);
                                            if (existingSlotFile) {
                                                await deleteGithubJsonFile(slotPath, existingSlotFile.sha, `Xóa bản lưu Slot ${game.githubSlot}`);
                                            }
                                            const { slots, sha: indexSha } = await getGithubSaveIndex();
                                            slots[game.githubSlot - 1] = null;
                                            await putGithubJsonFile(GITHUB_INDEX_PATH, { slots }, `Xóa chỉ mục lưu trữ - Slot ${game.githubSlot}`, indexSha);
                                            if (setSavedGames) {
                                                setSavedGames(prev => prev.filter(g => g.id !== game.id));
                                            }
                                        } else if (game.isSupabaseCloud && game.supabaseRowId) {
                                            const response = await fetch(`${SUPABASE_URL}/rest/v1/saves?id=eq.${game.supabaseRowId}`, {
                                                method: 'DELETE',
                                                headers: {
                                                    'apikey': SUPABASE_ANON_KEY,
                                                    'Authorization': `Bearer ${SUPABASE_ANON_KEY}`
                                                }
                                            });
                                            if (!response.ok) {
                                                const err = await response.text();
                                                throw new Error(err);
                                            }
                                            if (setSavedGames) {
                                                setSavedGames(prev => prev.filter(g => g.id !== game.id));
                                            }
                                        } else {
                                            await deleteDoc(doc(db, `artifacts/${appId}/users/${userId}/games`, game.id));
                                            if (setSavedGames) {
                                                setSavedGames(prev => prev.filter(g => g.id !== game.id));
                                            }
                                        }
                                        setModalMessage({ show: true, title: 'Đã Xóa', content: 'Đã xóa bản lưu thành công.', type: 'success' });
                                    } catch (error) {
                                        console.error("Error deleting game:", error);
                                        setModalMessage({ show: true, title: 'Lỗi', content: error.message, type: 'error' });
                                    }
                                },
                                confirmText: "Xóa Vĩnh Viễn",
                                cancelText: "Hủy"
                            });
                        }}
                        className="bg-transparent border border-[#8b1515]/60 hover:bg-[#8b1515]/20 text-[#ff4d4d] font-bold py-2.5 px-4 rounded-sm transition-all"
                    >
                        <TrashIcon className="w-4 h-4"/>
                    </button>
                </div>
              </div>
            )})}
          </div>
        )}
        <button
          onClick={() => setShowLoadGameModal(false)}
          className="mt-6 w-full bg-transparent border border-[#8ba888]/40 hover:bg-[#8ba888]/10 hover:border-[#8ba888] text-[#a3b8a3] hover:text-[#e8d3a1] font-bold py-3.5 px-4 rounded-sm shadow-md transition-colors uppercase tracking-widest text-xs"
        >
          Đóng
        </button>
      </div>
    </div>
);

