// HÀM MỚI: Lấy màu sắc cho VẬT PHẨM và KỸ NĂNG CHIẾN ĐẤU dựa trên phẩm chất
// Viền chữ đen mỏng cho các sắc thái trắng/xám nhạt (phẩm chất "Thường" trở xuống) —
// nếu không có viền, chữ gần như vô hình trên nền sáng (parchment). Xem báo cáo lỗi UI Hành Trang.
const RARITY_PALE_TEXT_OUTLINE = '[-webkit-text-stroke:0.5px_black] [paint-order:stroke_fill]';
const getItemRarityColor = (item) => {
    if (!item) return `text-gray-300 ${RARITY_PALE_TEXT_OUTLINE}`;

    // Kiểm tra cả Rarity (viết hoa) và rarity (viết thường)
    const rarity = item.Rarity || item.rarity;
    if (!rarity) return `text-gray-300 ${RARITY_PALE_TEXT_OUTLINE}`; // Mặc định nếu không có phẩm chất

    switch (rarity.toLowerCase()) {
        case 'thần thoại': return 'rarity-mythical font-extrabold';
        case 'huyền thoại': return 'text-red-500 animate-pulse drop-shadow-[0_0_8px_rgba(239,68,68,0.8)]';
        case 'siêu phẩm': return 'text-orange-400 animate-pulse drop-shadow-[0_0_5px_rgba(249,115,22,0.6)]';
        case 'cực phẩm': return 'text-purple-400';
        case 'hiếm': return 'text-blue-400';
        case 'tốt': return 'text-green-400';
        case 'thường': return `text-gray-100 ${RARITY_PALE_TEXT_OUTLINE}`;
        default: return `text-gray-300 ${RARITY_PALE_TEXT_OUTLINE}`;
    }
};
const getSkillColorClass = (skill) => {
    if (!skill) return 'text-gray-400';
    // Hàm getItemRarityColor mới đã tự xử lý logic hoa/thường, nên chỉ cần truyền thẳng skill vào
    return getItemRarityColor(skill); 
};


const getDisplayName = (entity) => {
    if (!entity) return null;
    return entity.Name || entity.name || entity.title || "Không rõ tên";
};
const formatHistoryItemForPrompt = (h, formatMode = 'text_nguoi') => {
    if (!h) return '';
    let contentString = '';
    const isXml = formatMode.startsWith('xml');
    const isActionNguoi = formatMode.endsWith('nguoi');

    if (h.type && h.type.includes('user')) {
        contentString = isActionNguoi ? `[Hành động của ngươi]: ${h.content}` : `[Hành động]: ${h.content}`;
    } else if (h.type === 'story' && Array.isArray(h.content)) {
        contentString = h.content.map(seg => {
            if (seg.type === 'narrative') return seg.content;
            if (seg.type === 'dialogue') {
                return isXml 
                    ? `<dialogue speaker="${seg.speaker}">${seg.content}</dialogue>`
                    : `${seg.speaker}: "${seg.content}"`;
            }
            return '';
        }).join(isXml ? '\n' : ' ');
    } else if (h.type === 'htab_dialogue_session' && Array.isArray(h.content)) {
        const htabName = h.htabName || "Hệ Thống";
        contentString = h.content.map(chat => {
            const speaker = chat.role === 'user' ? 'Ngươi' : htabName;
            return isXml
                ? `<dialogue speaker="${speaker}">${chat.content}</dialogue>`
                : `${speaker}: "${chat.content}"`;
        }).join(isXml ? '\n' : ' ');
    } else {
        contentString = typeof h.content === 'string' ? h.content : JSON.stringify(h.content);
    }
    return contentString;
};
const DialogueBubble = ({ speaker, content, playerName, characters, gameSettings, openQuickLoreModal }) => {
    const [displayAvatar, setDisplayAvatar] = useState(null);

    const speakerClean = (speaker || '').trim();
    const speakerLower = speakerClean.toLowerCase();
    const playerNameClean = (playerName || '').trim();
    const playerNameLower = playerNameClean.toLowerCase();

    const isPlayer = speakerClean === 'Ngươi' || speakerLower === 'ngươi' || speakerLower === playerNameLower;
    
    const displayName = isPlayer ? 'Ngươi' : speakerClean;
    const iconLetter = displayName.charAt(0).toUpperCase();

    // Tên chính xác để hệ thống tra cứu (Nếu là Ngươi thì tra tên thật của NVC)
    const targetLoreName = isPlayer ? playerNameClean : speakerClean;

    // Thiết kế thanh nhã: Nền gradient mờ, bo góc dạng bọt thoại thư pháp
    const bubbleClass = isPlayer
        ? 'bg-gradient-to-br from-[#162216]/90 to-[#0a0f0a]/90 border border-[#cda45e]/30 shadow-[0_4px_15px_rgba(0,0,0,0.3)] backdrop-blur-md self-end rounded-tl-2xl rounded-tr-2xl rounded-bl-2xl rounded-br-sm' 
        : 'bg-gradient-to-br from-[#0a0f0a]/90 to-[#101a10]/90 border border-[#8ba888]/30 shadow-[0_4px_15px_rgba(0,0,0,0.3)] backdrop-blur-md self-start rounded-tl-2xl rounded-tr-2xl rounded-bl-sm rounded-br-2xl'; 
        
    const alignmentClass = isPlayer ? 'items-end' : 'items-start';
    const nameClass = isPlayer ? 'text-[#cda45e] text-right' : 'text-[#8ba888] text-left';
    const avatarRingClass = isPlayer ? 'border-[#cda45e]/60' : 'border-[#8ba888]/60';

    useEffect(() => {
        let isMounted = true;

        const fetchAvatar = async () => {
            let targetChar = null;

            if (isPlayer) {
                if (gameSettings?.playerAvatarUrl) {
                    if(isMounted) setDisplayAvatar(gameSettings.playerAvatarUrl);
                    return;
                }
                if (characters) targetChar = characters.find(c => c.isPlayer);
            } else {
                if (characters) {
                    targetChar = characters.find(c => {
                        const cName = (c.Name || '').trim().toLowerCase();
                        return cName === speakerLower || speakerLower.includes(cName) || cName.includes(speakerLower);
                    });
                }
            }

            if (!targetChar) {
                if(isMounted) setDisplayAvatar(null);
                return;
            }

            if (targetChar.avatarStoredLocally && targetChar.id) {
                const base64 = await getAvatarFromIndexedDB(targetChar.id);
                if (isMounted && base64) {
                    setDisplayAvatar(base64);
                    return;
                }
            }
            
            if (targetChar.avatarBase64) {
                const src = targetChar.avatarBase64.startsWith('data:image') 
                    ? targetChar.avatarBase64 
                    : `data:image/jpeg;base64,${targetChar.avatarBase64}`;
                if(isMounted) setDisplayAvatar(src);
                return;
            }

            if (targetChar.avatarUrl) {
                if(isMounted) setDisplayAvatar(targetChar.avatarUrl);
                return;
            }

            if(isMounted) setDisplayAvatar(null);
        };

        fetchAvatar();

        return () => { isMounted = false; };
    }, [speakerLower, isPlayer, characters, gameSettings]);

    return (
        <div className={`w-full flex flex-col my-4 ${alignmentClass}`}>
            <div className="flex items-start gap-3" style={{ flexDirection: isPlayer ? 'row-reverse' : 'row' }}>
                
                {/* Phần Avatar: Giờ đây có thể BẤM VÀO ĐƯỢC */}
                <div 
                    onClick={() => openQuickLoreModal && openQuickLoreModal('auto-detect', targetLoreName)}
                    title={`Xem thông tin ${displayName}`}
                    className={`flex-shrink-0 w-11 h-11 rounded-full p-[2px] border ${avatarRingClass} shadow-[0_0_10px_rgba(0,0,0,0.5)] cursor-pointer hover:scale-110 hover:shadow-[0_0_15px_currentColor] transition-all duration-300`}
                >
                    <div className="w-full h-full rounded-full overflow-hidden bg-[#0a0f0a] flex items-center justify-center">
                        {displayAvatar ? (
                            <img 
                                src={displayAvatar} 
                                alt={displayName} 
                                className="w-full h-full object-cover opacity-90 hover:opacity-100 transition-opacity duration-300"
                                onError={(e) => { e.target.style.display='none'; }} 
                            />
                        ) : (
                            <span className={`text-sm font-bold ${isPlayer ? 'text-[#cda45e]' : 'text-[#8ba888]'}`} style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>{iconLetter}</span>
                        )}
                    </div>
                </div>

                {/* Phần Nội dung */}
                <div className="flex-grow max-w-[85%] mt-1">
                    {/* Phần Tên: Giờ đây có thể BẤM VÀO ĐƯỢC */}
                    <p 
                        onClick={() => openQuickLoreModal && openQuickLoreModal('auto-detect', targetLoreName)}
                        title={`Xem thông tin ${displayName}`}
                        className={`text-xs font-bold mb-1.5 tracking-widest uppercase opacity-90 ${nameClass} cursor-pointer hover:brightness-150 transition-all w-fit ${isPlayer ? 'ml-auto' : 'mr-auto'}`} 
                        style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}
                    >
                        {displayName}
                    </p>
                    
                    <div className={`py-3 px-4 text-[#e8d3a1] scale-text-sm leading-[1.7] ${bubbleClass}`}>
                        {content}
                    </div>
                </div>
            </div>
        </div>
    );
};


const StoryItem = React.memo(({ item, formatStoryText, playerName, onDelete, characters, gameSettings }) => {
    // Component bọc ngoài để xử lý hiệu ứng hover và hiển thị nút Xóa
    const Wrapper = ({ children, isSystemOrAction }) => (
        <div className={`relative group mb-5 ${isSystemOrAction ? '' : 'story-item'}`}>
            {children}
            <button
                onClick={() => onDelete && onDelete(item.id)}
                // opacity-0 + group-hover từng khiến nút này VÔ HÌNH và không thể
                // bấm được trên điện thoại (không có trạng thái hover). Chỉ ẩn theo
                // hover trên thiết bị thực sự có con trỏ chuột ([@media(hover:hover)]);
                // trên cảm ứng luôn hiện mờ (opacity-40) để còn bấm được.
                className="absolute top-2 right-2 p-2 flex items-center justify-center bg-[#0a0f0a]/90 border border-[#8b1515]/50 hover:bg-[#8b1515] hover:border-[#ff4d4d] rounded-sm text-[#ff4d4d] hover:text-white opacity-40 [@media(hover:hover)]:opacity-0 [@media(hover:hover)]:group-hover:opacity-100 group-focus-within:opacity-100 transition-all duration-300 z-10 shadow-[0_0_10px_rgba(139,21,21,0.5)]"
                style={{ minWidth: TOUCH_TARGET_MIN + 'px', minHeight: TOUCH_TARGET_MIN + 'px' }}
                title="Xóa khỏi lịch sử"
            >
                <TrashIcon className="w-4 h-4" />
            </button>
        </div>
    );

    // 1. Xử lý các loại item hệ thống/người dùng
    if (item.type !== 'story') {
        if (item.type === 'htab_dialogue_session') {
            const htabName = item.htabName || 'Hệ Thống';
            
            // Tách biệt giữa hội thoại trực tiếp và các phân cảnh miêu tả thức hải/tỉnh dậy/rời đi
            const isNarrative = (text) => {
                const lower = (text || '').toLowerCase().trim();
                return lower.startsWith('thần thức') || 
                       lower.startsWith('ngươi bừng tỉnh') || 
                       lower.startsWith('ngươi mở mắt') ||
                       lower.startsWith('thần trí') ||
                       lower.startsWith('linh hồn') ||
                       lower.includes('trở về thực tại') ||
                       lower.includes('quay trở lại thể xác') ||
                       lower.includes('biến động thể chất');
            };

            return (
                <Wrapper isSystemOrAction={true}>
                    <div className="my-6 py-4 border-y-2 border-dashed border-purple-500/40 relative">
                        <div className="text-center mb-4">
                            <span className="bg-[#0a0f0a] px-4 py-1 border border-purple-500/40 text-purple-300 font-bold text-xs tracking-[0.2em] uppercase rounded-full shadow-[0_0_10px_rgba(165,180,252,0.15)]">
                                ✦ Linh Cảnh Thức Hải ✦
                            </span>
                        </div>
                        <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2 custom-scrollbar-gold pt-2">
                            {item.content.map((chat, idx) => {
                                const isUser = chat.role === 'user';
                                
                                if (isUser) {
                                    return (
                                        <DialogueBubble
                                            key={idx}
                                            speaker="Ngươi"
                                            content={chat.content}
                                            playerName={playerName}
                                            characters={characters}
                                            gameSettings={gameSettings}
                                        />
                                    );
                                } else {
                                    if (isNarrative(chat.content)) {
                                        return (
                                            <div key={idx} className="whitespace-pre-line text-[#e8d3a1] leading-[1.8] scale-text-lg tracking-wide my-4 pl-4 border-l-2 border-purple-500/30 italic">
                                                {formatStoryText(chat.content)}
                                            </div>
                                        );
                                    } else {
                                        return (
                                            <DialogueBubble
                                                key={idx}
                                                speaker={htabName}
                                                content={chat.content}
                                                playerName={playerName}
                                                characters={characters}
                                                gameSettings={gameSettings}
                                            />
                                        );
                                    }
                                }
                            })}
                        </div>
                    </div>
                </Wrapper>
            );
        }

        let itemClass = 'bg-[#101a10]/60 border border-[#8ba888]/20 text-[#a3b8a3]';
        let headerText = null;

        if (item.type === 'user_choice' || item.type === 'user_custom_action') {
            itemClass = 'bg-[#162216]/80 border border-[#cda45e]/40 text-[#e8d3a1] shadow-[0_0_15px_rgba(205,164,94,0.05)] backdrop-blur-sm';
            headerText = item.type === 'user_custom_action' 
                ? <p className="font-bold text-[#cda45e] scale-text-xs mb-2 tracking-widest uppercase" style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>Hành động:</p>
                : <p className="font-bold text-[#cda45e] scale-text-xs mb-2 tracking-widest uppercase" style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>Đã chọn:</p>;
        } else if (item.type === 'system') {
             return (
                <Wrapper isSystemOrAction={true}>
                    <div className="py-3 px-5 bg-[#0a0f0a]/60 border-y border-[#cda45e]/30 text-[#8ba888] scale-text-sm flex items-start gap-3 whitespace-pre-line shadow-inner backdrop-blur-sm">
                        <InformationCircleIcon className="w-5 h-5 mt-0.5 flex-shrink-0 text-[#cda45e]" />
                        <div className="leading-relaxed italic">{formatStoryText(item.content)}</div>
                    </div>
                </Wrapper>
            );
        }

        const cleanedContent = typeof item.content === 'string' ? item.content.replace(/\*/g, '') : item.content;

        return (
            <Wrapper isSystemOrAction={true}>
                <div id={item.type.includes('user') ? `turn-start-${item.id}` : undefined} className={`p-4 relative rounded-sm ${itemClass}`}>
                    {/* Họa tiết góc kim loại cho hành động của người chơi */}
                    {(item.type === 'user_choice' || item.type === 'user_custom_action') && (
                        <>
                            <div className="absolute top-0 left-0 w-2 h-2 border-t border-l border-[#cda45e] pointer-events-none"></div>
                            <div className="absolute bottom-0 right-0 w-2 h-2 border-b border-r border-[#cda45e] pointer-events-none"></div>
                        </>
                    )}
                    {headerText}
                    <div className="prose prose-invert max-w-none text-current whitespace-pre-line leading-relaxed font-medium scale-text-base">
                        {cleanedContent}
                    </div>
                </div>
            </Wrapper>
        );
    }

    // 2. Xử lý Story (Văn bản truyện)
    if (typeof item.content === 'string') {
        return (
            <Wrapper isSystemOrAction={false}>
                <div className="whitespace-pre-line text-[#e8d3a1] leading-[1.8] scale-text-lg tracking-wide" style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>
                    {formatStoryText(item.content)}
                </div>
            </Wrapper>
        );
    }
    if (Array.isArray(item.content)) {
        return (
            <Wrapper isSystemOrAction={false}>
                <div className="text-[#e8d3a1] leading-[1.8] scale-text-lg tracking-wide" style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>
                    {formatStoryText(item.content)}
                </div>
            </Wrapper>
        );
    }
    return null;
});

function translateGeminiApiError(result, httpStatus) {
    const err = result?.error;
    if (!err) {
        return `Mã lỗi ${httpStatus}. Vui lòng kiểm tra API Key và quyền truy cập.`;
    }

    const details = err.details || [];
    const retryInfo = details.find(d => d['@type']?.includes('RetryInfo'));
    const retryDelay = retryInfo?.retryDelay?.replace('s', '') || null;
    const quotaFailure = details.find(d => d['@type']?.includes('QuotaFailure'));
    const violation = quotaFailure?.violations?.[0];
    const quotaLimit = violation?.quotaValue;
    const quotaModel = violation?.quotaDimensions?.model;

    switch (err.status) {
        case 'RESOURCE_EXHAUSTED':
            return `Đã vượt quá hạn mức miễn phí của Gemini`
                + (quotaModel ? ` cho model "${quotaModel}"` : '')
                + (quotaLimit ? ` (giới hạn ${quotaLimit} request)` : '')
                + `. Vui lòng thử lại sau${retryDelay ? ` khoảng ${retryDelay} giây` : ' ít phút'}, hoặc dùng API Key khác / bật thanh toán để tăng hạn mức.`;
        case 'PERMISSION_DENIED':
            return 'API Key không có quyền truy cập hoặc đã bị vô hiệu hóa. Vui lòng kiểm tra lại API Key trên Google AI Studio.';
        case 'UNAUTHENTICATED':
            return 'API Key không hợp lệ hoặc sai định dạng. Vui lòng kiểm tra lại.';
        case 'INVALID_ARGUMENT':
            return 'Yêu cầu gửi đi không hợp lệ (có thể API Key sai định dạng). Vui lòng kiểm tra lại.';
        case 'NOT_FOUND':
            return 'Không tìm thấy model được yêu cầu. Model có thể chưa khả dụng cho tài khoản của bạn.';
        default:
            return `Lỗi ${err.code || httpStatus}: ${err.message}`;
    }
}

function parseKeyValueString(kvString) {
    const result = {};
    if (!kvString || typeof kvString !== 'string') {
        return result;
    }
    const regex = /(\w+)\s*[:=]\s*(?:"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|([^,\]\s]*))/g;
    
    let match;

    while ((match = regex.exec(kvString)) !== null) {
        // match[1] là key
        const key = match[1].trim();
        let value = match[2] !== undefined ? match[2] :
                    match[3] !== undefined ? match[3] : match[4];
        
        // Dọn dẹp giá trị:
        // 1. Un-escape các ký tự đặc biệt như \" => "
        if (typeof value === 'string') {
            value = value.replace(/\\(.)/g, '$1');
            // 2. Trim khoảng trắng thừa
            value = value.trim();
        }

        result[key] = value;
    }
    
    if (Object.keys(result).length === 0) {
        kvString.split(',').forEach(pair => {
            const parts = pair.split(/[:=]/); // Tách bằng : hoặc =
            if (parts.length === 2) {
                const key = parts[0].trim();
                const value = parts[1].trim();
                if (key && value) {
                    result[key] = value;
                }
            }
        });
    }

    return result;
}
const hasLongAttribute = (val) => {
    if (val === null || typeof val !== 'object') return false;
    if (Array.isArray(val)) {
        return val.some(hasLongAttribute);
    }
    const keys = Object.keys(val);
    if (keys.some(k => k === 'customImageUrl' || k === 'avatarBase64' || k === 'images' || k === 'compressedData')) {
        return true;
    }
    return keys.some(k => hasLongAttribute(val[k]));
};

const putLongAttributesLast = (obj) => {
    if (obj === null || typeof obj !== 'object') return obj;

    if (Array.isArray(obj)) {
        return obj.map(putLongAttributesLast);
    }

    const keys = Object.keys(obj);
    const orderedObj = {};

    // Định nghĩa các thuộc tính có dung lượng lớn cần được đẩy xuống cuối file xuất
    const checkIsLongKey = (key) => {
        return key === 'customImageUrl' || 
               key === 'avatarBase64' || 
               key === 'images' || 
               key === 'compressedData' || 
               key === 'storyHistory' || 
               key === 'storySummaries';
    };

    // 1. Đưa các thuộc tính thông thường (không chứa bất kỳ ảnh, mã nén hay lịch sử dài) lên đầu tiên
    keys.forEach(key => {
        const isLongKey = checkIsLongKey(key);
        if (!isLongKey && !hasLongAttribute(obj[key])) {
            orderedObj[key] = putLongAttributesLast(obj[key]);
        }
    });

    // 2. Đưa các thuộc tính trung gian có chứa cấu trúc ảnh ở sâu bên trong (như 'effects', 'visual_effects') xuống sau
    keys.forEach(key => {
        const isLongKey = checkIsLongKey(key);
        if (!isLongKey && hasLongAttribute(obj[key])) {
            orderedObj[key] = putLongAttributesLast(obj[key]);
        }
    });

    // 3. Đưa các thuộc tính hình ảnh lớn, lịch sử câu chuyện và tóm tắt xuống vị trí cuối cùng của đối tượng
    keys.forEach(key => {
        const isLongKey = checkIsLongKey(key);
        if (isLongKey) {
            orderedObj[key] = putLongAttributesLast(obj[key]);
        }
    });

    return orderedObj;
};

const parseStatsBonus = (statsBonusString) => {
    const bonuses = {};
    if (statsBonusString && typeof statsBonusString === 'string' && statsBonusString.trim() !== '[Không có]') {
        statsBonusString.split(',').forEach(part => {
            const [key, value] = part.split(':').map(s => s.trim());
            if (key && !isNaN(parseFloat(value))) {
                bonuses[key.toLowerCase()] = parseFloat(value);
            }
        });
    }
    return bonuses;
};

const calculateEffectPower = (powerComponents, caster, target, contextValues = {}) => {
    if (!powerComponents || !Array.isArray(powerComponents)) {
        return 0;
    }

    let totalPower = 0;
    powerComponents.forEach(component => {
        if (!component || typeof component !== 'object') return;

        const sourceStatRaw = component.source_stat || component.stat || component.stat_name || component.source || 'ATK';
        const scaleNumberRaw = component.scale_number !== undefined ? component.scale_number : (component.scale !== undefined ? component.scale : (component.value !== undefined ? component.value : 100));
        const basedOnRaw = component.based_on || component.based || 'caster';
        const conditions = component.conditions;

        if (conditions && Array.isArray(conditions) && conditions.length > 0) {
            if (!checkEffectConditions(caster, target, conditions)) {
                return;
            }
        }

        const parsedScale = parseFloat(scaleNumberRaw);
        const safeScaleNumber = (isNaN(parsedScale) ? 100 : ((parsedScale > 0 && parsedScale <= 5.0) ? parsedScale * 100 : parsedScale));

        const sourceStatStr = String(sourceStatRaw).toUpperCase().trim();
        if (sourceStatStr === 'FIXED_VALUE' || sourceStatStr === 'FIXED') {
            totalPower += safeScaleNumber;
            return;
        }
        // LAST_DAMAGE_DEALT: dùng cho hiệu ứng kích hoạt bởi trigger ON_DEAL_DAMAGE (VD: hút máu theo % sát thương vừa gây ra).
        // Đây là giá trị ngữ cảnh thời điểm (không phải chỉ số cố định của caster/target), không cần sourceEntity.
        if (sourceStatStr === 'LAST_DAMAGE_DEALT') {
            totalPower += (contextValues.lastDamageDealt || 0) * (safeScaleNumber / 100.0);
            return;
        }

        const sourceEntity = (basedOnRaw === 'target' ? target : caster) || caster;
        if (!sourceEntity) return;

        let normalizedStat = sourceStatStr;
        if (normalizedStat.startsWith('ATK') || normalizedStat.startsWith('ATTACK')) normalizedStat = 'ATK';
        else if (normalizedStat.startsWith('DEF') || normalizedStat.startsWith('DEFENSE')) normalizedStat = 'DEF';
        else if (normalizedStat.startsWith('SPD') || normalizedStat.startsWith('SPEED')) normalizedStat = 'SPD';
        else if (normalizedStat.startsWith('HP') || normalizedStat.startsWith('HEALTH') || normalizedStat === 'MAX_HP' || normalizedStat === 'MAXHP') normalizedStat = 'MAX_HP';
        else if (normalizedStat.startsWith('CR') || normalizedStat.startsWith('CRIT')) {
            if (normalizedStat.includes('DMG') || normalizedStat.includes('DAMAGE')) normalizedStat = 'CDMG';
            else normalizedStat = 'CR';
        }

        let statValue = 0;
        switch (normalizedStat) {
            case 'ATK': statValue = sourceEntity.atk || 0; break;
            case 'DEF': statValue = sourceEntity.def || 0; break;
            case 'SPD': statValue = sourceEntity.spd || 0; break;
            case 'MAX_HP': statValue = sourceEntity.maxhp || 0; break;
            case 'CURRENT_HP': statValue = sourceEntity.hp || 0; break;
            case 'MISSING_HP': statValue = (sourceEntity.maxhp || 0) - (sourceEntity.hp || 0); break;
            case 'BASE_ATK': statValue = sourceEntity.baseAtk || 0; break;
            default:
                statValue = sourceEntity.atk || 0;
                console.warn(`Chỉ số không xác định trong power_component: ${sourceStatRaw} (Mặc định về ATK)`);
        }
        
        totalPower += statValue * (safeScaleNumber / 100.0);
    });

    return isNaN(totalPower) ? 0 : totalPower;
};


const calculateFinalDamage = (caster, target, rawDamage, skillProperties = {}) => {
    const properties = skillProperties || {};
    const { 
        true_damage = false, 
        armor_penetration = 0,      
        flat_armor_penetration = 0, 
        can_crit = true,
        cannot_be_dodged = false
    } = properties;
    let wasCrit = false;
    let wasDodged = false;
    
    if (!cannot_be_dodged) {
        const evasionChance = target.evasion || 0;
        if ((Math.random() * 100) < evasionChance) {
            wasDodged = true;
            return { 
                finalDamage: 0, 
                potentialDamage: Math.floor(rawDamage),
                wasCrit: false, 
                wasDodged: true, 
                damageAbsorbedByShield: 0 
            };
        }
    }

    let potentialDamage = rawDamage;

    if (can_crit && (Math.random() * 100) < (caster.cr || 0)) {
        potentialDamage *= ((caster.cdmg || 150) / 100);
        wasCrit = true;
    }

    const totalDmgAmp = (caster.dmgAmp || 0) / 100.0;
    potentialDamage *= (1 + totalDmgAmp);
    
    let damageAfterDefense = potentialDamage;
    if (!true_damage) {
        const baseDef = Math.max(0, (target.def || 0) - flat_armor_penetration);
        const effectiveDef = Math.max(0, baseDef * (1 - armor_penetration));
        
        const K_DEFENSE = GAME_CONFIG.damageFormula.defenseBaseK + ((target.level || 1) - 1) * GAME_CONFIG.damageFormula.defensePerLevelK;
        const defenseReduction = effectiveDef / (effectiveDef + K_DEFENSE);
        damageAfterDefense *= (1 - defenseReduction);

        const totalDmgResPercent = target.dmgRes || 0;
        damageAfterDefense *= (1 - totalDmgResPercent / 100);
    }

    damageAfterDefense = Math.max(0, damageAfterDefense);
    
    let remainingDamage = damageAfterDefense;
    let damageAbsorbedByShield = 0;
    
    if ((target.shield || 0) > 0) {
        damageAbsorbedByShield = Math.min(target.shield, remainingDamage);
        remainingDamage -= damageAbsorbedByShield;
    }
    
    const targetStatuses = [...(target.longTermStatuses || []), ...(target.combatStatuses || [])];
    const hasDamageImmunity = targetStatuses.some(s => (STATUS_LIBRARY[s.status_id] || s).special_flags?.includes("DAMAGE_IMMUNITY_ALL"));
    if (hasDamageImmunity) {
        return { 
            finalDamage: 0, 
            potentialDamage: Math.floor(potentialDamage), 
            wasCrit, 
            wasDodged, 
            damageAbsorbedByShield: Math.floor(damageAbsorbedByShield) 
        };
    }

    const finalDamageInt = remainingDamage > 0 ? Math.max(1, Math.floor(remainingDamage)) : 0;
    
    return {
        finalDamage: finalDamageInt,
        potentialDamage: Math.floor(potentialDamage),
        wasCrit: wasCrit,
        wasDodged: wasDodged,
        damageAbsorbedByShield: Math.floor(damageAbsorbedByShield)
    };
};

const calculateFinalHealing = (target, rawHeal) => {
    if (!target || rawHeal <= 0) {
        return 0;
    }
    const healingModifier = target.incomingHealing || 1;
    let finalHeal = rawHeal * healingModifier;
    finalHeal = Math.max(0, finalHeal);
    return Math.floor(finalHeal);
};


const getActualTargets = (caster, designatedTarget, allCombatants, targetDefinition) => {
    const playerPartyIds = allCombatants.filter(c => c.isPlayer || c.isCompanion).map(c => c.id);
    const casterIsPlayerSide = playerPartyIds.includes(caster.id);

    const allies = allCombatants.filter(c => casterIsPlayerSide ? playerPartyIds.includes(c.id) : !playerPartyIds.includes(c.id));
    const enemies = allCombatants.filter(c => casterIsPlayerSide ? !playerPartyIds.includes(c.id) : playerPartyIds.includes(c.id));

    const aliveAllies = allies.filter(c => c.hp > 0);
    const aliveEnemies = enemies.filter(c => c.hp > 0);

    // Chuẩn hóa loại mục tiêu đề phòng AI viết sai chính tả hoặc sai thứ tự từ
    let targetType = (targetDefinition.type || '').toLowerCase().trim();
    if (targetType === 'enemy_single' || targetType === 'single-enemy') targetType = 'single_enemy';
    if (targetType === 'enemy_all' || targetType === 'all_enemy') targetType = 'all_enemies';
    if (targetType === 'ally_single' || targetType === 'single-ally') targetType = 'single_ally';
    if (targetType === 'ally_all' || targetType === 'all_ally') targetType = 'all_allies';

    switch (targetType) {
        case 'self':
            return caster.hp > 0 ? [caster] : [];

        case 'single':
        case 'single_target':
        case 'target':
            if (designatedTarget && designatedTarget.hp > 0) {
                return [designatedTarget];
            }
            return aliveEnemies.length > 0 ? [aliveEnemies[0]] : [];

        case 'single_enemy':
            if (designatedTarget && designatedTarget.hp > 0 && enemies.some(e => e.id === designatedTarget.id)) {
                return [designatedTarget];
            }
            return aliveEnemies.length > 0 ? [aliveEnemies[0]] : [];

        case 'single_ally':
            if (designatedTarget && designatedTarget.hp > 0 && allies.some(a => a.id === designatedTarget.id)) {
                return [designatedTarget];
            }
            const lowestHpAlly = aliveAllies
                .filter(a => a.id !== caster.id)
                .sort((a, b) => a.hp - b.hp);
            return lowestHpAlly.length > 0 ? [lowestHpAlly[0]] : (caster.hp > 0 ? [caster] : []);

        case 'all_allies':
            return aliveAllies;

        case 'all_enemies':
            return aliveEnemies;

        case 'random_enemy': {
            if (aliveEnemies.length === 0) return [];
            const count = targetDefinition.count || 1;
            const shuffled = [...aliveEnemies].sort(() => 0.5 - Math.random());
            return shuffled.slice(0, count);
        }
        
        case 'splash': {
             if (!designatedTarget || designatedTarget.hp <= 0) return [];
             
             const primaryTarget = designatedTarget;
             const otherEnemies = aliveEnemies.filter(e => e.id !== primaryTarget.id);
             
             if (otherEnemies.length === 0) return [primaryTarget];

             const splashCount = targetDefinition.count || 2;
             
             const shuffledOthers = [...otherEnemies].sort(() => 0.5 - Math.random());
             const secondaryTargets = shuffledOthers.slice(0, splashCount);
             
             return [primaryTarget, ...secondaryTargets];
        }

        default:
            console.warn(`Loại mục tiêu không xác định: "${targetDefinition.type}"`);
            return [];
    }
};



const checkEffectConditions = (caster, target, conditions, triggerContext = null) => {
    if (!conditions || !Array.isArray(conditions) || conditions.length === 0) {
        return true;
    }
    let allConditionsMet = true;

    for (const cond of conditions) {
        const trigger = cond.trigger;
        const isTriggerBasedCondition = trigger.startsWith('ON_');
        if (isTriggerBasedCondition) {
            if (triggerContext === null) {
                allConditionsMet = false;
                break; // Thoát vòng lặp ngay lập tức
            }
            if (triggerContext !== trigger) {
                allConditionsMet = false;
                break;
            }
            continue;
        }
        switch (trigger) {
            case 'TARGET_HP_BELOW': {
                const subject = triggerContext ? caster : target;
                if (!subject || subject.maxhp <= 0) {
                    allConditionsMet = false;
                    break;
                }
                
                const hpPercent = subject.hp / subject.maxhp;
                if (hpPercent >= cond.value) {
                    allConditionsMet = false; 
                }
                break;
            }

            case 'TARGET_HAS_DEBUFF_TYPE': {
                const subject = triggerContext ? caster : target;
                if (!subject || !subject.combatStatuses) {
                    allConditionsMet = false;
                    break;
                }
                
                const hasDebuff = subject.combatStatuses.some(status => {
                    const statusDef = STATUS_LIBRARY[status.status_id] || status;
                    if (cond.value === 'CC') {
                        return statusDef.special_flags?.includes("SKIP_TURN");
                    }
                    if (cond.value === 'SOFT_CC') {
                        return statusDef.special_flags?.includes("CANNOT_USE_ACTIVE_SKILLS");
                    }
                    return statusDef.status_type === cond.value.toLowerCase();
                });

                if (!hasDebuff) {
                    allConditionsMet = false; // Điều kiện không thỏa mãn
                }
                break;
            }
            
            default:
                console.warn(`Gặp phải trigger điều kiện không xác định: ${trigger}`);
                break;
        }

        // Nếu có bất kỳ điều kiện nào không thỏa mãn, thoát vòng lặp ngay
        if (!allConditionsMet) {
            break;
        }
    }

    return allConditionsMet;
};

const parseEffectsString = (effectsString) => {
    if (!effectsString || typeof effectsString !== 'string') return [];
    
    return effectsString.split(';').map(effectStr => {
        const [type, dataPart] = effectStr.split(/:(.*)/s);
        if (!type || !dataPart) return null;

        const effectData = parseKeyValueString(dataPart);
        const action = { type: type.trim().toLowerCase() }; 

        switch (action.type) {
            case 'damage':
                action.target = { type: effectData.target || 'single_enemy' };
                action.power_components = [{
                    source_stat: effectData.formula.includes(':') ? 'FIXED_VALUE' : effectData.formula.split('*')[0].toUpperCase(),
                    scale_number: parseFloat(effectData.formula.includes(':') ? effectData.formula.split(':')[1] : (effectData.formula.split('*')[1] || 1)),
                    based_on: 'caster'
                }];
                
                const specialProps = {};
                if (effectData.true_damage === 'true') {
                    specialProps.true_damage = true;
                }
                if (effectData.armor_penetration) {
                    const penetrationValue = parseFloat(effectData.armor_penetration);
                    if (!isNaN(penetrationValue)) {
                        specialProps.armor_penetration = penetrationValue / 100.0; 
                    }
                }
                if (effectData.can_crit === 'false') {
                    specialProps.can_crit = false;
                }
                if (Object.keys(specialProps).length > 0) {
                    action.special_properties = specialProps;
                }
                break;

            case 'heal':
                action.target = { type: effectData.target || 'self' };
                action.power_components = [{
                    source_stat: effectData.formula.includes(':') ? 'FIXED_VALUE' : effectData.formula.split('*')[0].toUpperCase(),
                    scale_number: parseFloat(effectData.formula.includes(':') ? effectData.formula.split(':')[1] : (effectData.formula.split('*')[1] || 1)),
                    based_on: 'caster'
                }];
                break;
            case 'apply_status':
                action.target = { type: effectData.target || 'single_enemy' };
                action.status_to_apply = {
                    status_id: effectData.status_id,
                    duration: parseInt(effectData.duration, 10) || 1
                };
                if (effectData.chance) action.chance = parseFloat(effectData.chance);
                break;
            case 'apply_dynamic_status':
                action.target = { type: effectData.target || 'single_enemy' };
                action.status_to_apply = {
                    status_name: effectData.name,
                    status_type: effectData.type,
                    duration: parseInt(effectData.duration, 10) || 1,
                    stat_modifications: (effectData.stat_changes || "").split(',').map(mod => {
                        const [stat, val] = mod.split(':');
                        if (!stat || !val) return null;
                        const isPercent = stat.toUpperCase().endsWith('_PERCENT');
                        return {
                            stat_name: stat.toUpperCase().replace('_PERCENT', ''),
                            modifier_type: isPercent ? 'percentage' : 'flat',
                            value: parseFloat(val)
                        };
                    }).filter(Boolean)
                };
                break;
            default:
                return null;
        }
        
        return { action };

    }).filter(Boolean);
};

const processSkill = (caster, designatedTarget, allCombatants, skillData, currentRound) => {
    const changeset = { stateChanges: [], logs: [], skillUpdates: [], combatEvents: [] };

    const isEnemy = !caster.isPlayer && !caster.isCompanion;
    if (isEnemy) {
        console.log(`\n⚔️ [DEBUG - QUÁI XUẤT CHIÊU] ${caster.Name} dùng ${skillData.Name}`);
        console.log(`Dữ liệu State hiện tại của chiêu này:`, JSON.stringify(skillData.effects, null, 2));
    }

    if (skillData.cooldown > 0 && skillData.skillType !== 'item_as_skill') {
        changeset.skillUpdates.push({ casterId: caster.id, skillId: skillData.id, newCooldown: skillData.cooldown });
    }

    let lastTargets = [];
    // Tổng sát thương đã gây ra bởi các effect 'damage' TRƯỚC ĐÓ trong CÙNG một lần dùng chiêu này
    // (VD: chiêu AOE đánh 4 mục tiêu rồi hồi máu bằng 100% "sát thương gây ra" -> phải là TỔNG của cả 4 đòn, không phải 0/đòn cuối).
    let totalDamageDealtInSkill = 0;
    const effectsToProcess = skillData.effects || (skillData.effectsString ? parseEffectsString(skillData.effectsString) : []);

    if (isEnemy && effectsToProcess.length === 0) {
        console.error(`🚨 [LỖI NGHIÊM TRỌNG] Mảng effects của chiêu ${skillData.Name} bị RỖNG! AI tạo sai cấu trúc hoặc State bị mất dữ liệu.`);
    }

    effectsToProcess.forEach((effect, index) => {
        if (effect.chance !== undefined && Math.random() > effect.chance) return;
        const action = effect.action || effect;
        if (!action.target) {
            console.warn(`🚨 [LỖI] Effect thứ ${index} của chiêu ${skillData.Name} bị thiếu 'target'. AI tạo sai Schema!`);
            return;
        }

        let currentActualTargets = getActualTargets(caster, designatedTarget, allCombatants, action.target);
        if (currentActualTargets.length > 0) lastTargets = [...currentActualTargets];

        currentActualTargets.forEach(target => {
            const finalCaster = calculateFinalStats(caster);
            const finalTarget = calculateFinalStats(target);
            if (!checkEffectConditions(finalCaster, finalTarget, action.conditions)) return;
                    
            const effectType = (action.type || '').toLowerCase();

            const logBase = {
                id: crypto.randomUUID(), round: currentRound, actor: getDisplayName(caster),
                actorId: caster.id, skill: skillData.Name, target: getDisplayName(target), targetId: target.id,
                damageDealt: { direct: 0, dot: 0, item: 0, summon: 0 },
                damageMitigated: { reduction: 0, shield: 0, dodge: 0 },
                healingDone: 0, shieldGranted: 0,
            };
            let messageParts = [];

            switch (effectType) {
                case 'damage': {
                    let rawDamage = calculateEffectPower(action.power_components, finalCaster, finalTarget);
                    
                    if (!rawDamage || isNaN(rawDamage) || rawDamage <= 0) {
                        rawDamage = (finalCaster.atk || 20) * 1.0;
                    }

                    const { finalDamage, potentialDamage, wasCrit, wasDodged, damageAbsorbedByShield } = calculateFinalDamage(finalCaster, finalTarget, rawDamage, action.special_properties);
                    
                    if (wasDodged) {
                        messageParts.push(`đã bị né!`);
                        logBase.damageMitigated.dodge = potentialDamage;
                        changeset.combatEvents.push({ type: 'DODGE', targetId: target.id, casterId: caster.id });
                        break;
                    }
                    
                    logBase.damageMitigated.reduction = Math.max(0, potentialDamage - finalDamage - damageAbsorbedByShield);
                    logBase.damageMitigated.shield = damageAbsorbedByShield;

                    if (finalDamage > 0) {
                        changeset.stateChanges.push({ targetId: target.id, change: { hp: -finalDamage } });
                        if (skillData.skillType === 'item_as_skill') logBase.damageDealt.item = finalDamage;
                        else logBase.damageDealt.direct = finalDamage;
                        totalDamageDealtInSkill += finalDamage;
                        messageParts.push(`gây ${finalDamage} sát thương`);
                    } else {
                        messageParts.push(`gây 0 sát thương (bị phòng ngự cản phá hoàn toàn)`);
                    }
                    
                    if (damageAbsorbedByShield > 0) {
                        changeset.stateChanges.push({ targetId: target.id, change: { shield: -damageAbsorbedByShield } });
                        messageParts.push(`(${damageAbsorbedByShield} bị khiên hấp thụ)`);
                    }
                    
                    if (wasCrit) {
                        messageParts.push(`(Chí mạng!)`);
                        changeset.combatEvents.push({ type: 'CRITICAL_HIT', targetId: target.id, casterId: caster.id });
                    }
                    
                    break;
                }
                
                case 'heal': {
                    let rawHealAmount = calculateEffectPower(action.power_components, finalCaster, finalTarget, { lastDamageDealt: totalDamageDealtInSkill });

                    if (!rawHealAmount || isNaN(rawHealAmount) || rawHealAmount <= 0) {
                        rawHealAmount = (finalCaster.maxhp || 200) * 0.15;
                    }

                    const finalHealAmount = calculateFinalHealing(finalTarget, rawHealAmount);
                    if (finalHealAmount > 0) {
                        changeset.stateChanges.push({ targetId: target.id, change: { hp: +finalHealAmount } });
                        messageParts.push(`hồi ${finalHealAmount} HP.`);
                        if (skillData.skillType === 'item_as_skill') {
                            logBase.healingDone = { item: finalHealAmount, skill: 0 };
                        } else {
                            logBase.healingDone = { item: 0, skill: finalHealAmount };
                        }
                    }
                    break;
                }
                
                case 'apply_status': 
                case 'apply_dynamic_status':
                {
                    const statusBlueprint = action.status_to_apply;
                    if (!statusBlueprint) {
                        console.warn(`🚨 [LỖI] AI định buff/debuff nhưng quên tạo 'status_to_apply' trong chiêu ${skillData.Name}`);
                        break;
                    }
                    
                    const statusInstance = { 
                        instanceId: crypto.randomUUID(), 
                        sourceSkillName: skillData.Name,
                        ...statusBlueprint, 
                        duration: action.duration || statusBlueprint.duration || 1 
                    };

                    changeset.stateChanges.push({ targetId: target.id, change: { add_status: statusInstance } });
                    
                    const statusName = statusBlueprint.status_name || statusBlueprint.status_id;
                    messageParts.push(`áp dụng [${statusName}].`);

                    (statusBlueprint.stat_modifications || []).forEach(mod => {
                        if (mod.stat_name === 'SHIELD' && mod.modifier_type === 'flat') {
                            let shieldAmount = 0;
                            if (mod.power_components) {
                                shieldAmount = calculateEffectPower(mod.power_components, finalCaster, finalTarget);
                            } else {
                                shieldAmount = mod.value || 0;
                            }
                            
                            if (!shieldAmount || isNaN(shieldAmount) || shieldAmount <= 0) {
                                shieldAmount = (finalCaster.maxhp || 200) * 0.15;
                            }

                            if (shieldAmount > 0) {
                                changeset.stateChanges.push({ targetId: target.id, change: { shield: +shieldAmount } });
                                logBase.shieldGranted = shieldAmount;
                                messageParts.push(`tạo ${Math.floor(shieldAmount)} Khiên.`);
                            }
                        }
                    });
                    break;
                }
                case 'reduce_current_stat': {
                    const statKey = action.stat_to_reduce?.toLowerCase();
                    if (statKey && finalTarget.hasOwnProperty(statKey)) {
                        const reductionAmount = finalTarget[statKey] * (action.reduction_percent || 0);
                        if (reductionAmount > 0) {
                            changeset.stateChanges.push({ 
                                targetId: target.id, 
                                change: { [statKey]: -reductionAmount } 
                            });
                            messageParts.push(`làm suy yếu, mất ${Math.floor(reductionAmount)} ${statKey.toUpperCase()}.`);
                        }
                    }
                    break;
                }
                case 'dispel': {
                    const count = action.count || 1;
                    changeset.stateChanges.push({
                        targetId: target.id,
                        change: {
                            dispel_debuffs: { count: count }
                        }
                    });
                    messageParts.push(`giải trừ ${count} hiệu ứng xấu.`);
                    break;
                }
                default:
                    console.warn(`🚨 [LỖI] Kỹ năng ${skillData.Name} có action type lạ: ${effectType}`);
                    break;
            }
            
            if (messageParts.length > 0) {
                logBase.message = messageParts.join(' ');
                changeset.logs.push(logBase);
            }
        });
    });

    return changeset;
};

// Ngưỡng EXP để 1 kỹ năng (đã có field exp — tức tạo mới sau khi có tính năng EXP kỹ năng) tăng lên 1 bậc phẩm chất.
const calculateMaxSkillExpForRarity = (rarity) => GAME_CONFIG.skillExpToNextRarity[rarity] ?? null;

// Tăng 1 bậc phẩm chất cho kỹ năng: nhân toàn bộ chỉ số sức mạnh theo đúng tỉ lệ rarityBaseValue giữa 2 bậc,
// giảm hồi chiêu 1 (chỉ kỹ năng chiến đấu), cập nhật ngưỡng EXP mới. Mutate trực tiếp trên object truyền vào.
const handleSkillRarityUp = (skill) => {
    const rarityEntries = Object.entries(GAME_CONFIG.rarityBaseValue);
    const currentIndex = rarityEntries.findIndex(([name]) => name === skill.Rarity);
    if (currentIndex === -1 || currentIndex >= rarityEntries.length - 1) return; // Không xác định hoặc đã tối đa

    const [, currentValue] = rarityEntries[currentIndex];
    const [nextRarity, nextValue] = rarityEntries[currentIndex + 1];
    const ratio = nextValue / currentValue;

    // 1. Nhân toàn bộ power_components/stat_modifications trong effects theo đúng tỉ lệ
    (skill.effects || []).forEach(effectEntry => {
        const action = effectEntry.action || effectEntry;
        if (Array.isArray(action.power_components)) {
            action.power_components.forEach(pc => {
                if (typeof pc.scale_number === 'number') pc.scale_number *= ratio;
            });
        }
        const statMods = action.status_to_apply?.stat_modifications;
        if (Array.isArray(statMods)) {
            statMods.forEach(mod => {
                if (typeof mod.value === 'number') mod.value *= ratio;
                if (Array.isArray(mod.power_components)) {
                    mod.power_components.forEach(pc => {
                        if (typeof pc.scale_number === 'number') pc.scale_number *= ratio;
                    });
                }
            });
        }
    });

    // 2. Nhân song song từng số trong chuỗi Stats phẳng (bản tóm tắt dễ đọc, đồng bộ với effects)
    if (skill.Stats) {
        const parsedStats = parseKeyValueString(skill.Stats);
        const scaledEntries = Object.entries(parsedStats).map(([key, value]) => {
            const numericValue = parseFloat(value);
            return `${key}:${Number.isFinite(numericValue) ? Math.round(numericValue * ratio) : value}`;
        });
        skill.Stats = scaledEntries.join(',');
    }

    // 3. Giảm hồi chiêu 1 (floor 0) — chỉ áp dụng cho kỹ năng chiến đấu
    if (skill.skillType === 'combat' && typeof skill.cooldown === 'number') {
        skill.cooldown = Math.max(0, skill.cooldown - 1);
    }

    // 4. Cập nhật phẩm chất mới + ngưỡng EXP mới
    skill.Rarity = nextRarity;
    skill.maxExp = calculateMaxSkillExpForRarity(nextRarity);
};

// Cộng EXP cho 1 kỹ năng, tự động xử lý tăng phẩm (có thể tăng nhiều bậc cùng lúc nếu EXP dư nhiều).
// Bỏ qua hoàn toàn nếu kỹ năng chưa có field exp (kỹ năng tạo trước khi có tính năng này).
const addSkillExp = (skill, amount) => {
    if (!skill || skill.exp === undefined || skill.exp === null) return;
    if (skill.Rarity === 'Thần Thoại') return; // Đã tối đa, khoá EXP

    if (!skill.maxExp || skill.maxExp <= 0) {
        skill.maxExp = calculateMaxSkillExpForRarity(skill.Rarity);
    }

    skill.exp += amount;

    while (skill.maxExp > 0 && skill.exp >= skill.maxExp && skill.Rarity !== 'Thần Thoại') {
        skill.exp -= skill.maxExp;
        handleSkillRarityUp(skill);
        if (skill.Rarity === 'Thần Thoại') {
            skill.exp = 0;
            break;
        }
    }
};

class CombatLoop {
    constructor(combatants, onStateChange, onActionRequest, onCombatEnd, combatType, sharedCooldowns, onAnimateAction, onPvPActionGenerated, onCallCombatAI) {
        this.allCombatants = JSON.parse(JSON.stringify(combatants));
        this.isPlayerPresent = this.allCombatants.some(c => c.isPlayer);
        this.turnOrderQueue = [];
        this.currentRound = 0;
        this.currentTurnTaker = null;
        this.combatType = combatType || 'Lethal';
        this.onStateChange = onStateChange;
        this.onActionRequest = onActionRequest;
        this.onCombatEnd = onCombatEnd;
        this.sharedCooldowns = { ...(sharedCooldowns || { tactical: 0, potion: 0 }) };
        this.onAnimateAction = onAnimateAction; 
        this.onPvPActionGenerated = onPvPActionGenerated; 
        this.onCallCombatAI = onCallCombatAI; // Ghi nhận hàm gọi AI Combat siêu nhẹ
        this.combatEnded = false;
        this.nextCompanionCommand = null;
        this.isFirstTurnOfCombat = true;

        this.allCombatants.forEach(char => {
            char.triggeredEffectUses = {}; 
            Object.values(char.equippedItems || {}).filter(Boolean).forEach(item => {
                (item.effects || []).forEach((effect, index) => {
                    effect.instanceId = `${item.id}_effect_${index}`;
                });
            });
        });

        // Ràng buộc (bind) tất cả các hàm để không bị mất context
        this.start = this.start.bind(this);
        this.startNewRound = this.startNewRound.bind(this);
        this.calculateTurnOrder = this.calculateTurnOrder.bind(this);
        this.nextTurn = this.nextTurn.bind(this);
        this.handleAction = this.handleAction.bind(this);
        this.applyChangeset = this.applyChangeset.bind(this);
        this.applyStatus = this.applyStatus.bind(this);
        this.processStartOfTurnEffects = this.processStartOfTurnEffects.bind(this);
        this.processEndOfTurnEffects = this.processEndOfTurnEffects.bind(this);
        this.isControlled = this.isControlled.bind(this);
        this.checkCombatEnd = this.checkCombatEnd.bind(this);
        this.processTriggeredEffects = this.processTriggeredEffects.bind(this);
        this.getAvailableActions = this.getAvailableActions.bind(this);
        this.setNextCompanionCommand = this.setNextCompanionCommand.bind(this);
    }

    setNextCompanionCommand(command) {
        this.nextCompanionCommand = command;
    }

    start() {
        if (this.isFirstTurnOfCombat) {
            this.allCombatants.forEach(c => {
                const startChangeset = this.processTriggeredEffects('ON_COMBAT_START', c);
                if (startChangeset.stateChanges.length > 0) {
                    this.applyChangeset(startChangeset);
                    this.onStateChange(this.allCombatants, startChangeset.logs, startChangeset);
                }
            });
            this.isFirstTurnOfCombat = false;
        }
        this.startNewRound();
    }

    startNewRound() {
        this.currentRound++;
        this.turnOrderQueue = this.calculateTurnOrder();
        this.onStateChange(this.allCombatants, [], { newRound: this.currentRound });
        this.nextTurn();
    }

    calculateTurnOrder() {
        let alive = this.allCombatants.filter(c => c.hp > 0);
        if (this.combatType === 'Sandbox') {
            alive = alive.filter(c => c.isPlayer || c.isCompanion);
        }

        let order = alive.sort((a, b) => {
            if (b.spd !== a.spd) return b.spd - a.spd;
            return a.id.localeCompare(b.id);
        }).map(c => c.id);

        const spds = alive.map(c => c.spd);
        if (spds.length > 1) {
            const maxSpd = Math.max(...spds);
            const minSpd = Math.max(1, Math.min(...spds));
            if (maxSpd / minSpd >= 2) {
                const fastChars = alive.filter(c => c.spd >= minSpd * 2);
                fastChars.forEach(c => order.push(c.id)); 
            }
        }
        return order;
    }

    async nextTurn() {
        try {
            if (this.checkCombatEnd()) return;

            if (this.turnOrderQueue.length === 0) {
                this.startNewRound();
                return;
            }

            const nextId = this.turnOrderQueue.shift();
            this.currentTurnTaker = this.allCombatants.find(c => c.id === nextId);

            if (!this.currentTurnTaker || this.currentTurnTaker.hp <= 0) {
                this.nextTurn();
                return;
            }

            const startOfTurnChangeset = this.processStartOfTurnEffects(this.currentTurnTaker.id);
            if (startOfTurnChangeset.stateChanges.length > 0) {
                this.applyChangeset(startOfTurnChangeset);
                this.onStateChange(this.allCombatants, startOfTurnChangeset.logs, startOfTurnChangeset);
            }

            if (this.checkCombatEnd()) return;

            if (!this.currentTurnTaker || this.currentTurnTaker.hp <= 0) {
                this.nextTurn();
                return;
            }

            const isCtrl = this.isControlled(this.currentTurnTaker);

            let flavorText = '';
            if (this.currentTurnTaker.isCompanion && this.nextCompanionCommand) {
                flavorText = `(Lệnh: ${this.nextCompanionCommand})`;
                this.nextCompanionCommand = null;
            }

            this.onActionRequest(this.currentTurnTaker, false, {
                isControlled: isCtrl,
                availableActions: this.getAvailableActions(this.currentTurnTaker),
                flavorText: flavorText
            }, this);
        } catch (error) {
            // Bất kỳ lỗi bất ngờ nào ở đây (VD: dữ liệu nhân vật hình nhân/quái bất thường) trước đây sẽ làm
            // nextTurn() văng lỗi âm thầm, onActionRequest không bao giờ được gọi -> giao diện kẹt vĩnh viễn
            // ở màn hình "đang xử lý". Giờ luôn trả quyền hành động về cho người chơi để tránh kẹt trận.
            console.error("[CombatLoop] Lỗi khi xử lý nextTurn(), trả quyền hành động về người chơi để tránh kẹt trận:", error);
            const fallbackActor = (this.currentTurnTaker && (this.currentTurnTaker.isPlayer || this.currentTurnTaker.isCompanion))
                ? this.currentTurnTaker
                : this.allCombatants.find(c => c.isPlayer && c.hp > 0);
            if (fallbackActor) {
                this.currentTurnTaker = fallbackActor;
                this.onActionRequest(fallbackActor, false, {
                    isControlled: false,
                    availableActions: this.getAvailableActions(fallbackActor),
                    flavorText: ''
                }, this);
            }
        }
    }

    getAvailableActions(char) {
        if (!char) return [];
        let actions = ["Đánh thường"];
        
        let skills = char.isPlayer || char.isCompanion 
            ? Object.values(char.equippedSkills || {}).filter(Boolean) 
            : (char.skills || []);

        skills.forEach(skill => {
            if (skill.skillType === 'combat' && (skill.currentCooldown || 0) === 0) {
                actions.push(skill.Name);
            }
        });

        if (char.isPlayer || char.isCompanion) {
            const playerChar = this.allCombatants.find(c => c.isPlayer);
            const inventory = playerChar ? (playerChar.inventory || []) : [];
            
            const hasPotions = inventory.some(i => i.Type === 'Đan dược');
            const hasTactical = inventory.some(i => i.Type === 'Đa năng');
            
            if (hasPotions && (char.potionCooldown || 0) === 0) actions.push("Dùng Đan dược");
            if (hasTactical && (this.sharedCooldowns.tactical || 0) === 0) actions.push("Dùng Vật phẩm Đa năng");
            if (this.combatType === 'Sandbox') {
                actions.push("Rời khỏi");
            } else {
                actions.push("Bỏ chạy");
            }
        }
        return actions;
    }



    processTriggeredEffects(triggerName, character, context = null) {
        const changeset = { stateChanges: [], logs: [] };
        if (!character || character.hp <= 0) return changeset;

        if (!character.triggeredEffectUses) {
            character.triggeredEffectUses = {};
        }

        const equippableItems = Object.values(character.equippedItems || {}).filter(Boolean);
        const equippedSkillsList = Object.values(character.equippedSkills || {}).filter(Boolean);
        // Quét cả vật phẩm trang bị lẫn kỹ năng đang trang bị — hiệu ứng bị động (VD: hút máu) thường nằm trên kỹ năng/vũ khí, không chỉ vật phẩm.
        const sourcesToScan = [...equippableItems, ...equippedSkillsList];

        sourcesToScan.forEach(source => {
            const effects = source.effects || (source.effectsString ? parseEffectsString(source.effectsString) : []);
            effects.forEach((effect, index) => {
                const action = effect.action || effect;
                const conditions = effect.conditions || action.conditions;
                if (!conditions) return;

                const meetsCondition = conditions.some(cond => cond.trigger === triggerName);
                if (meetsCondition) {
                    const effectId = effect.instanceId || `${source.id}_effect_${index}`;
                    if (effect.limitations?.type === 'per_combat') {
                        const uses = character.triggeredEffectUses[effectId] || 0;
                        if (uses >= effect.limitations.value) return;
                        character.triggeredEffectUses[effectId] = uses + 1;
                    }

                    if (action.type === 'apply_status' || action.type === 'apply_dynamic_status') {
                        const statusBlueprint = action.status_to_apply;
                        const statusInstance = {
                            instanceId: crypto.randomUUID(),
                            sourceSkillName: source.Name,
                            ...statusBlueprint,
                            duration: action.duration || statusBlueprint.duration || 1
                        };
                        changeset.stateChanges.push({ targetId: character.id, change: { add_status: statusInstance } });
                        changeset.logs.push({
                            id: crypto.randomUUID(), round: this.currentRound, actor: character.Name,
                            skill: source.Name, target: character.Name,
                            message: `kích hoạt hiệu ứng ẩn, nhận [${statusBlueprint.status_name || statusBlueprint.status_id}]!`
                        });
                    } else if (action.type === 'heal') {
                        // VD điển hình: hút máu — HEAL với power_component source_stat="LAST_DAMAGE_DEALT", trigger ON_DEAL_DAMAGE.
                        const contextValues = { lastDamageDealt: context?.lastDamageDealt || 0 };
                        const contextTarget = context?.target || null;
                        const rawHealAmount = calculateEffectPower(action.power_components, character, contextTarget, contextValues);
                        const finalHealAmount = calculateFinalHealing(character, rawHealAmount);
                        if (finalHealAmount > 0) {
                            changeset.stateChanges.push({ targetId: character.id, change: { hp: +finalHealAmount } });
                            changeset.logs.push({
                                id: crypto.randomUUID(), round: this.currentRound, actor: character.Name,
                                skill: source.Name, target: character.Name,
                                message: `kích hoạt hiệu ứng ẩn từ [${source.Name}], hồi ${finalHealAmount} HP!`
                            });
                        }
                    }
                }
            });
        });

        return changeset;
    }

    async handleAction(skillData, designatedTargetId, preCalculatedChangeset = null) {
        if (this.combatEnded) return;

        const caster = this.currentTurnTaker;
        let mainChangeset; 
        let targetsBeforeAction; 

        if (preCalculatedChangeset) {
            mainChangeset = preCalculatedChangeset;
        } else {
            if (skillData.skillType === 'item_as_skill') {
                const consumeChange = { targetId: this.allCombatants.find(c => c.isPlayer).id, change: { consume_item: { itemId: skillData.id, quantity: 1 } } };
                mainChangeset = processSkill(caster, designatedTargetId ? this.allCombatants.find(c => c.id === designatedTargetId) : null, this.allCombatants, skillData, this.currentRound);
                mainChangeset.stateChanges.push(consumeChange);
                if (skillData.originalItemType === 'Đa năng') { this.sharedCooldowns.tactical = 5; this.sharedCooldowns.justUsedTactical = true; } 
                else if (skillData.originalItemType === 'Đan dược') { const ownerIndex = this.allCombatants.findIndex(c => c.id === caster.id); if (ownerIndex > -1) { this.allCombatants[ownerIndex].potionCooldown = 3; this.allCombatants[ownerIndex].justUsedPotion = true; } }
            } else {
                const designatedTarget = designatedTargetId ? this.allCombatants.find(c => c.id === designatedTargetId) : null;
                mainChangeset = processSkill(caster, designatedTarget, this.allCombatants, skillData, this.currentRound);
                if (skillData) {
                    const skillOwner = (caster.isPlayer || caster.isCompanion) ? caster : this.allCombatants.find(c => c.id === caster.id);
                    // Đấu Tập với hình nhân chỉ cho bằng NỬA kinh nghiệm kỹ năng so với chiến đấu thực tế.
                    const skillExpGain = this.combatType === 'Sandbox' ? GAME_CONFIG.skillExpPerUse / 2 : GAME_CONFIG.skillExpPerUse;
                    if (skillOwner) {
                        if (skillOwner.equippedSkills) { for (const slot in skillOwner.equippedSkills) { if (skillOwner.equippedSkills[slot]?.id === skillData.id) { if (skillData.cooldown > 0) { skillOwner.equippedSkills[slot].currentCooldown = skillData.cooldown; skillOwner.equippedSkills[slot].justUsed = true; } addSkillExp(skillOwner.equippedSkills[slot], skillExpGain); break; } } }
                        if (skillOwner.skills) { const skillIndex = skillOwner.skills.findIndex(s => s.id === skillData.id); if (skillIndex > -1) { if (skillData.cooldown > 0) { skillOwner.skills[skillIndex].currentCooldown = skillData.cooldown; skillOwner.skills[skillIndex].justUsed = true; } addSkillExp(skillOwner.skills[skillIndex], skillExpGain); } }
                    }
                }
            }
            mainChangeset.sharedCooldowns = this.sharedCooldowns;
        }
        this.prePrefetchNextTurnAI(mainChangeset);

        if (this.combatType === 'PvP' && !preCalculatedChangeset) {
            if (this.onAnimateAction) {
                await this.onAnimateAction({ casterId: caster.id, targetId: designatedTargetId, skill: skillData, changeset: mainChangeset });
            }
            if (this.onPvPActionGenerated) {
                this.onPvPActionGenerated({ skillData, designatedTargetId, changeset: mainChangeset });
            }
            this.applyChangeset(mainChangeset);
            this.onStateChange(this.allCombatants, mainChangeset.logs, mainChangeset);
            
            if (this.checkCombatEnd()) {
                this.processEndOfTurnEffects(caster.id);
                return; 
            }
            this.processEndOfTurnEffects(caster.id);
            if (!this.combatEnded) this.nextTurn();
            return;
        }

        targetsBeforeAction = mainChangeset.stateChanges
            .map(change => this.allCombatants.find(c => c.id === change.targetId))
            .filter(Boolean)
            .map(c => ({ id: c.id, hp: c.hp }));

        if (this.onAnimateAction) {
            await this.onAnimateAction({ casterId: caster.id, targetId: designatedTargetId, skill: skillData, changeset: mainChangeset });
        }

        this.applyChangeset(mainChangeset);
        this.onStateChange(this.allCombatants, mainChangeset.logs, mainChangeset);

        if (this.checkCombatEnd()) {
            this.processEndOfTurnEffects(caster.id);
            return; 
        }
        
        (mainChangeset.combatEvents || []).forEach(event => {
            if (event.type === 'CRITICAL_HIT') {
                const onCritChangeset = this.processTriggeredEffects('ON_CRITICAL_HIT', caster);
                if(onCritChangeset.stateChanges.length > 0) {
                     this.applyChangeset(onCritChangeset);
                     this.onStateChange(this.allCombatants, onCritChangeset.logs, onCritChangeset);
                }
            } else if (event.type === 'DODGE') {
                const target = this.allCombatants.find(c => c.id === event.targetId);
                if(target) {
                    const onDodgeChangeset = this.processTriggeredEffects('ON_DODGE', target);
                    if(onDodgeChangeset.stateChanges.length > 0) {
                         this.applyChangeset(onDodgeChangeset);
                         this.onStateChange(this.allCombatants, onDodgeChangeset.logs, onDodgeChangeset);
                    }
                }
            }
        });
        if (this.checkCombatEnd()) { this.processEndOfTurnEffects(caster.id); return; }
        
        const defeatedTargets = targetsBeforeAction.filter(t_before => {
            const t_after = this.allCombatants.find(c => c.id === t_before.id);
            return t_before.hp > 0 && t_after && t_after.hp <= 0;
        });

        if (defeatedTargets.length > 0) {
            const onDefeatChangeset = this.processTriggeredEffects('ON_ENEMY_DEFEATED', caster);
            if (onDefeatChangeset.stateChanges.length > 0) {
                this.applyChangeset(onDefeatChangeset);
                this.onStateChange(this.allCombatants, onDefeatChangeset.logs, onDefeatChangeset);
            }
        }
        if (this.checkCombatEnd()) { this.processEndOfTurnEffects(caster.id); return; }

        const onSkillUseChangeset = this.processTriggeredEffects('ON_SKILL_USE', caster, { target: designatedTargetId ? this.allCombatants.find(c => c.id === designatedTargetId) : null });
        if (onSkillUseChangeset.stateChanges.length > 0) {
            this.applyChangeset(onSkillUseChangeset);
            this.onStateChange(this.allCombatants, onSkillUseChangeset.logs, onSkillUseChangeset);
        }
        if (this.checkCombatEnd()) { this.processEndOfTurnEffects(caster.id); return; }

        if (skillData.skillCategory === 'ultimate') {
            const onUltimateUseChangeset = this.processTriggeredEffects('ON_ULTIMATE_USE', caster, { target: designatedTargetId ? this.allCombatants.find(c => c.id === designatedTargetId) : null });
            if(onUltimateUseChangeset.stateChanges.length > 0) {
                 this.applyChangeset(onUltimateUseChangeset);
                 this.onStateChange(this.allCombatants, onUltimateUseChangeset.logs, onUltimateUseChangeset);
            }
        }
        if (this.checkCombatEnd()) { this.processEndOfTurnEffects(caster.id); return; }

        (mainChangeset.stateChanges || []).forEach(change => {
            const target = this.allCombatants.find(c => c.id === change.targetId);
            if (!target) return;
            if (change.change.hp && change.change.hp < 0) {
                const damageDealt = Math.abs(change.change.hp);
                const onTakeDamageChangeset = this.processTriggeredEffects('ON_TAKE_DAMAGE', target, { caster: caster });
                 if(onTakeDamageChangeset.stateChanges.length > 0) {
                     this.applyChangeset(onTakeDamageChangeset);
                     this.onStateChange(this.allCombatants, onTakeDamageChangeset.logs, onTakeDamageChangeset);
                 }
                const onHpBelowChangeset = this.processTriggeredEffects('ON_HP_BELOW', target, { caster: caster });
                if(onHpBelowChangeset.stateChanges.length > 0) {
                    this.applyChangeset(onHpBelowChangeset);
                    this.onStateChange(this.allCombatants, onHpBelowChangeset.logs, onHpBelowChangeset);
                }
                // Kích hoạt phía người GÂY sát thương (VD: hút máu). Đối xứng với ON_TAKE_DAMAGE ở phía người NHẬN.
                const onDealDamageChangeset = this.processTriggeredEffects('ON_DEAL_DAMAGE', caster, { target: target, lastDamageDealt: damageDealt });
                if (onDealDamageChangeset.stateChanges.length > 0) {
                    this.applyChangeset(onDealDamageChangeset);
                    this.onStateChange(this.allCombatants, onDealDamageChangeset.logs, onDealDamageChangeset);
                }
            }
        });
        
        if (this.checkCombatEnd()) { this.processEndOfTurnEffects(caster.id); return; }
        
        this.processEndOfTurnEffects(caster.id);
        this.allCombatants.forEach(combatant => {
            if (combatant.combatStatuses && combatant.combatStatuses.length > 0) {
                combatant.combatStatuses.forEach(status => {
                    if (status.justApplied) delete status.justApplied;
                });
            }
        });

        if (!this.combatEnded) {
            this.nextTurn();
        }
    }

    prePrefetchNextTurnAI(mainChangeset) {
        this.preFetchedActionPromise = null;
        this.preFetchedActionId = null;

        if (this.combatType === 'PvP') return; 

        const tempCombatants = JSON.parse(JSON.stringify(this.allCombatants));
        const tempQueue = [...this.turnOrderQueue];

        mainChangeset.stateChanges.forEach(change => {
            const target = tempCombatants.find(c => c.id === change.targetId);
            if (target) {
                if (change.change.hp) {
                    target.hp = Math.max(0, target.hp + change.change.hp);
                }
            }
        });

        const playerPartyAlive = tempCombatants.some(c => (c.isPlayer || c.isCompanion) && c.hp > 0);
        const enemyPartyAlive = tempCombatants.some(c => !(c.isPlayer || c.isCompanion) && c.hp > 0);
        if (!playerPartyAlive || !enemyPartyAlive) {
            return; 
        }

        let nextId = null;
        while (tempQueue.length > 0) {
            const id = tempQueue.shift();
            const char = tempCombatants.find(c => c.id === id);
            if (char && char.hp > 0) {
                nextId = id;
                break;
            }
        }

        if (!nextId) {
            let alive = tempCombatants.filter(c => c.hp > 0);
            let order = alive.sort((a, b) => b.spd - a.spd).map(c => c.id);
            if (order.length > 0) {
                nextId = order[0];
            }
        }

        if (!nextId) return;

        const nextTurnTaker = tempCombatants.find(c => c.id === nextId);
        const isNpc = nextTurnTaker && !nextTurnTaker.isPlayer && (!nextTurnTaker.isCompanion || !this.isPlayerPresent);

        if (isNpc) {
            this.preFetchedActionId = nextId;
            
            // Kích hoạt API Combat siêu nhẹ chạy ngầm không chứa lịch sử truyện
            if (this.onCallCombatAI) {
                this.preFetchedActionPromise = this.onCallCombatAI(nextTurnTaker, this.allCombatants);
                console.log(`⚡ [Pre-fetch] Đã kích hoạt API chuẩn bị trước cho lượt của NPC: ${nextTurnTaker.Name}`);
            }
        }
    }

    applyChangeset(changeset) {
        changeset.stateChanges.forEach(change => {
            const targetIndex = this.allCombatants.findIndex(c => c.id === change.targetId);
            if (targetIndex === -1) return;

            const targetCharacter = this.allCombatants[targetIndex];
            const changeType = Object.keys(change.change)[0];
            const changeValue = change.change[changeType];

            switch (changeType) {
                case 'hp':
                    targetCharacter.hp += changeValue;
                    break;
                case 'shield':
                    targetCharacter.shield = (targetCharacter.shield || 0) + changeValue;
                    break;
                case 'add_status':
                    this.applyStatus(targetIndex, changeValue);
                    break;
                case 'remove_status_id':
                    targetCharacter.combatStatuses = (targetCharacter.combatStatuses || []).filter(
                        status => status.instanceId !== changeValue
                    );
                    break;
                case 'consume_item': {
                    const { itemId, quantity } = changeValue;
                    if (!targetCharacter.inventory) break;

                    const itemIndex = targetCharacter.inventory.findIndex(invItem => invItem.id === itemId);
                    if (itemIndex > -1) {
                        const inventoryItem = targetCharacter.inventory[itemIndex];
                        if (inventoryItem.quantity && inventoryItem.quantity > 1) {
                            inventoryItem.quantity -= quantity;
                            if (inventoryItem.quantity <= 0) targetCharacter.inventory.splice(itemIndex, 1);
                        } else {
                            targetCharacter.inventory.splice(itemIndex, 1);
                        }
                    }
                    break;
                }
                case 'dispel_debuffs': {
                    if (!targetCharacter.combatStatuses) break;
                    const count = changeValue.count || 1;
                    let debuffsDispelled = 0;
                    
                    targetCharacter.combatStatuses = targetCharacter.combatStatuses.reverse().filter(status => {
                        if ((status.status_type === 'debuff' || status.type === 'debuff') && status.is_dispellable !== false && debuffsDispelled < count) {
                            debuffsDispelled++;
                            return false; 
                        }
                        return true;
                    }).reverse();
                    break;
                }
            }
        });

        this.allCombatants.forEach((char, index) => {
            char.hp = Math.min(char.maxhp, Math.max(0, char.hp));
            char.shield = Math.max(0, (char.shield || 0));
            if(char.skills) {
                char.skills.forEach(skill => { skill.currentCooldown = Math.max(0, skill.currentCooldown); });
            }
            if (char.combatStatuses) {
                this.allCombatants[index].combatStatuses = char.combatStatuses.filter(status => {
                    if (status.duration <= 0) {
                        changeset.logs.push({
                           id: crypto.randomUUID(), round: this.currentRound, actor: char.Name,
                           skill: "Hết hiệu lực", target: char.Name, message: `trạng thái "${status.status_name || status.name}" đã kết thúc.`
                        });
                        return false;
                    }
                    return true;
                });
            }
        });

        if (changeset.skillUpdates) {
             changeset.skillUpdates.forEach(update => {
                const casterIndex = this.allCombatants.findIndex(c => c.id === update.casterId);
                if (casterIndex === -1) return;
                const skillOwner = this.allCombatants[casterIndex];
                
                if (skillOwner.equippedSkills) {
                    for (const slot in skillOwner.equippedSkills) {
                        if (skillOwner.equippedSkills[slot]?.id === update.skillId) {
                            skillOwner.equippedSkills[slot].currentCooldown = update.newCooldown;
                        }
                    }
                }
                if (skillOwner.skills) {
                    const skillIndex = skillOwner.skills.findIndex(s => s.id === update.skillId);
                    if (skillIndex > -1) {
                        skillOwner.skills[skillIndex].currentCooldown = update.newCooldown;
                    }
                }
            });
        }
        this.allCombatants = [...this.allCombatants];
    }

    applyStatus(targetIndex, statusToAdd) {
        const target = this.allCombatants[targetIndex];
        if (!target.combatStatuses) target.combatStatuses = [];

        const baseStatus = STATUS_LIBRARY[statusToAdd.status_id] || {};
        const finalStatusBlueprint = { ...baseStatus, ...statusToAdd };

        const existingStatusIndex = target.combatStatuses.findIndex(s => s.status_name === finalStatusBlueprint.status_name);

        if (existingStatusIndex > -1) {
            const existingStatus = target.combatStatuses[existingStatusIndex];
            if (finalStatusBlueprint.stackable && finalStatusBlueprint.stackable.max_stacks > 1) {
                existingStatus.current_stacks = Math.min(
                    finalStatusBlueprint.stackable.max_stacks, 
                    (existingStatus.current_stacks || 1) + 1
                );
            }
            existingStatus.duration = finalStatusBlueprint.duration;
            existingStatus.justApplied = true;
        } else {
            target.combatStatuses.push({
                ...finalStatusBlueprint,
                instanceId: statusToAdd.instanceId || crypto.randomUUID(),
                sourceSkillName: statusToAdd.sourceSkillName || 'Không rõ',
                duration: statusToAdd.duration || finalStatusBlueprint.duration,
                current_stacks: 1,
                justApplied: true
            });
        }
    }

    processStartOfTurnEffects(turnTakerId) {
        const changeset = { stateChanges: [], logs: [] };
        const charIndex = this.allCombatants.findIndex(c => c.id === turnTakerId);
        if (charIndex === -1) return changeset;

        const character = this.allCombatants[charIndex];

        if (character.combatStatuses && character.combatStatuses.length > 0) {
            character.combatStatuses.forEach(status => {
                if (status.justApplied) return;

                if (status.effects_on_tick && Array.isArray(status.effects_on_tick)) {
                    status.effects_on_tick.forEach(effect => {
                        const caster = character;
                        const target = character;

                        if (effect.type === 'damage') {
                            const rawDamage = calculateEffectPower(effect.power_components, caster, target);
                            const { finalDamage, wasCrit } = calculateFinalDamage(caster, target, rawDamage, effect.special_properties);
                            if (finalDamage > 0) {
                                changeset.stateChanges.push({ targetId: target.id, change: { hp: -finalDamage } });
                                let critText = wasCrit ? " (Chí mạng!)" : "";
                                changeset.logs.push({
                                    id: crypto.randomUUID(), round: this.currentRound, actor: target.Name,
                                    skill: `Hiệu ứng ${status.status_name || status.name}`, target: target.Name,
                                    message: `mất ${finalDamage} HP${critText}.`
                                });
                            }
                        }

                        if (effect.type === 'heal') {
                            const rawHealAmount = calculateEffectPower(effect.power_components, caster, target);
                            const finalHealAmount = calculateFinalHealing(target, rawHealAmount);
                            if (finalHealAmount > 0) {
                                changeset.stateChanges.push({ targetId: target.id, change: { hp: +finalHealAmount } });
                                changeset.logs.push({
                                    id: crypto.randomUUID(), round: this.currentRound, actor: target.Name,
                                    skill: `Hiệu ứng ${status.status_name || status.name}`, target: target.Name,
                                    message: `hồi ${finalHealAmount} HP.`
                                });
                            }
                        }
                    });
                }
            });
        }
        
        const triggerChangeset = this.processTriggeredEffects('ON_TURN_START', character);
        if (triggerChangeset.stateChanges.length > 0) {
            changeset.stateChanges.push(...triggerChangeset.stateChanges);
            changeset.logs.push(...triggerChangeset.logs);
        }
        
        return changeset;
    }

    processEndOfTurnEffects(turnTakerId) {
        const turnTakerIndex = this.allCombatants.findIndex(c => c.id === turnTakerId);
        if (turnTakerIndex === -1) return;

        const turnTaker = this.allCombatants[turnTakerIndex];

        if (turnTaker.potionCooldown > 0) {
            if (turnTaker.justUsedPotion) {
                delete turnTaker.justUsedPotion;
            } else {
                turnTaker.potionCooldown = Math.max(0, turnTaker.potionCooldown - 1);
            }
        }

        if (turnTaker.equippedSkills) {
            for (const slot in turnTaker.equippedSkills) {
                const skill = turnTaker.equippedSkills[slot];
                if (skill) {
                    if (skill.justUsed) delete skill.justUsed;
                    else skill.currentCooldown = Math.max(0, (skill.currentCooldown || 0) - 1);
                }
            }
        }
        if (turnTaker.skills) {
            turnTaker.skills.forEach(skill => {
                if (skill.justUsed) delete skill.justUsed;
                else skill.currentCooldown = Math.max(0, (skill.currentCooldown || 0) - 1);
            });
        }

        if (turnTaker.combatStatuses && turnTaker.combatStatuses.length > 0) {
            turnTaker.combatStatuses = turnTaker.combatStatuses
                .map(status => {
                    const newStatus = { ...status };
                    if (!newStatus.justApplied) newStatus.duration = (newStatus.duration || 1) - 1;
                    return newStatus;
                })
                .filter(status => {
                    if (status.duration <= 0) {
                        const statusName = status.status_name || status.name || "Không rõ";
                        this.onStateChange([], [{ type: 'system', content: `**[Hệ thống]** Hiệu ứng "${statusName}" trên ${turnTaker.Name} đã kết thúc.` }]);
                        return false;
                    }
                    return true;
                });
        }

        let cooldownsDidChange = false;
        if (turnTaker.isPlayer || turnTaker.isCompanion) {
            if (this.sharedCooldowns.tactical > 0) {
                if (this.sharedCooldowns.justUsedTactical) {
                    delete this.sharedCooldowns.justUsedTactical;
                } else {
                    let reduction = 1; 
                    const player = this.allCombatants.find(c => c.isPlayer);
                    if (player) {
                        const adventureSkills = Object.values(player.equippedSkills || {}).filter(s => s && s.skillType === 'adventure');
                        adventureSkills.forEach(skill => {
                            (skill.passive_effects || []).forEach(effect => {
                                if (effect.type === 'REDUCE_POTION_COOLDOWN') {
                                    reduction += effect.value || 0;
                                }
                            });
                        });
                    }
                    this.sharedCooldowns.tactical = Math.max(0, this.sharedCooldowns.tactical - reduction);
                }
                cooldownsDidChange = true;
            }
        }
        
        if (cooldownsDidChange) {
            this.onStateChange(this.allCombatants, [], { sharedCooldowns: this.sharedCooldowns });
        }
    }

    isControlled(character) {
        const statuses = character.combatStatuses || [];
        const hasImmunity = statuses.some(s => {
            const sDef = STATUS_LIBRARY[s.status_id] || s;
            return sDef.special_flags && sDef.special_flags.includes("CROWD_CONTROL_IMMUNITY");
        });

        if (hasImmunity) return false;

        return statuses.some(s => {
            const sDef = STATUS_LIBRARY[s.status_id] || s;
            if (sDef.special_flags && sDef.special_flags.includes("SKIP_TURN")) return true;
            if (s.stat_modifications) {
                return s.stat_modifications.some(mod => mod.stat_name === "ACTION_DISABLED" && mod.value > 0);
            }
            return false;
        });
    }

    checkCombatEnd() {
        if (this.combatEnded) return true;

        const playerPartyAlive = this.allCombatants.some(c => (c.isPlayer || c.isCompanion) && c.hp > 0);
        const enemyPartyAlive = this.allCombatants.some(c => !(c.isPlayer || c.isCompanion) && c.hp > 0);

        if (!playerPartyAlive || !enemyPartyAlive) {
            this.combatEnded = true;

            const playerParty = this.allCombatants.filter(c => c.isPlayer || c.isCompanion);
            const enemyParty = this.allCombatants.filter(c => !c.isPlayer && !c.isCompanion);

            const outcomeData = {
                winningSideInfo: playerPartyAlive ? playerParty : enemyParty,
                losingSideInfo: playerPartyAlive ? enemyParty : playerParty
            };
            
            this.onCombatEnd(playerPartyAlive ? 'VICTORY' : 'DEFEAT', outcomeData, this.sharedCooldowns);
            return true;
        }
        return false;
    }
}


