                             <AvatarDisplay entity={character} className="w-[80vw] h-[80vh] max-w-[600px] max-h-[600px] pointer-events-none" shapeClass="rounded-none border-4 border-[#cda45e]/50 drop-shadow-[0_0_50px_rgba(205,164,94,0.3)]" readOnly={true} />
