const calculateFinalBuyPrice = (itemToBuy, difficulty, buyBonuses = {}, playerCharacter) => {
    if (!itemToBuy || !itemToBuy.Value) return 0;
    const baseValue = parseInt(itemToBuy.Value, 10) || 0;

    // --- BƯỚC 1: TÍNH HỆ SỐ MUA (TĨNH) ---
    const difficultyMultipliers = DIFFICULTY_MULTIPLIERS[difficulty] || DIFFICULTY_MULTIPLIERS['Thường'];
    let baseBuyMultiplier = difficultyMultipliers.buy; // Ví dụ: 1.3 cho độ khó Thường

    // Áp dụng bonus giảm giá mua từ kỹ năng phiêu lưu (làm giảm hệ số)
    if (playerCharacter) {
        const equippedSkills = Object.values(playerCharacter.equippedSkills || {}).filter(Boolean);
        let totalReductionPercent = 0;
        equippedSkills.forEach(skill => {
            (skill.passive_effects || []).forEach(effect => {
                if (effect.type === 'DECREASE_BUY_PRICE_MODIFIER') {
                    totalReductionPercent += effect.value; // value là %, ví dụ: 5, 10
                }
            });
        });
        // Giảm trực tiếp vào hệ số. Ví dụ: 1.3 - (5/100) = 1.25
        baseBuyMultiplier -= (totalReductionPercent / 100.0);
    }
    
    // Đảm bảo hệ số không bị âm
    baseBuyMultiplier = Math.max(0, baseBuyMultiplier);

    // --- BƯỚC 2: LẤY HỆ SỐ THƯƠNG LƯỢNG (ĐỘNG) TỪ AI ---
    // Đây là giá trị mà AI quyết định, mặc định là 1 (100%)
    const negotiationMultiplier = buyBonuses[itemToBuy.Name] !== undefined ? buyBonuses[itemToBuy.Name] : 1;

    // --- BƯỚC 3: TÍNH GIÁ CUỐI CÙNG ---
    const finalPrice = baseValue * baseBuyMultiplier * negotiationMultiplier;

    return Math.floor(finalPrice);
};

const calculateFinalSellValue = (playerOffer, sellMultiplier, itemSpecificSellBonuses, difficulty, playerCharacter) => {
    const multipliers = DIFFICULTY_MULTIPLIERS[difficulty] || DIFFICULTY_MULTIPLIERS['Thường'];
    let finalSellMultiplier = multipliers.sell;

    // Áp dụng bonus tăng giá bán từ kỹ năng phiêu lưu
    if (playerCharacter) {
        const equippedSkills = Object.values(playerCharacter.equippedSkills || {}).filter(Boolean);
        equippedSkills.forEach(skill => {
            (skill.passive_effects || []).forEach(effect => {
                if (effect.type === 'INCREASE_SELL_PRICE_MODIFIER') {
                    finalSellMultiplier += (effect.value / 100.0); // Chuyển từ % sang số thập phân
                }
            });
        });
    }

    const totalValueAfterNegotiation = playerOffer.reduce((total, offerItem) => {
        const itemBaseValue = parseInt(offerItem.Value, 10) || 0;
        const itemSpecificMultiplier = itemSpecificSellBonuses[offerItem.Name];
        
        // Ưu tiên kỳ vọng riêng của vật phẩm, nếu không có thì dùng kỳ vọng chung
        const Y_negotiation = itemSpecificMultiplier !== undefined ? itemSpecificMultiplier : (sellMultiplier || 0);
        
        const singleItemFinalValue = itemBaseValue * Y_negotiation;
        const totalValueForItem = singleItemFinalValue * (offerItem.quantity || 1);
        
        return total + totalValueForItem;
    }, 0);

    const finalCalculatedValue = Math.floor(totalValueAfterNegotiation * finalSellMultiplier);

    return {
        finalSellValue: finalCalculatedValue,
        baseSellMultiplier: finalSellMultiplier,
        negotiationMultiplier: sellMultiplier 
    };
};


const STAT_NAME_MAPPINGS = {
    level: 'Cấp Độ',
    hp: 'Sinh Lực',
    maxhp: 'Sinh Lực Tối Đa',
    atk: 'Tấn Công',
    def: 'Phòng Thủ',
    spd: 'Tốc Độ',
    cr: 'Tỉ Lệ Chí Mạng',
    cdmg: 'Sát Thương Chí Mạng',
    evasion: 'Né Tránh',
    hp_percent: '% Sinh Lực Cơ Bản',
    atk_percent: '% Tấn Công Cơ Bản',
    def_percent: '% Phòng Thủ Cơ Bản',
    spd_percent: '% Tốc Độ Cơ Bản',
    hp_amp: '% Tổng Sinh Lực',
    atk_amp: '% Tổng Tấn Công',
    def_amp: '% Tổng Phòng Thủ',
    spd_amp: '% Tổng Tốc Độ',
    dmg_amp: 'Khuếch Đại Sát Thương',
    dmg_res: 'Chống Chịu',
    carry_weight: 'Sức chứa',
    carry_weight_percent: '% Sức chứa',
    gender: 'Giới tính',
    attack: 'Tấn Công',
    defense: 'Phòng Thủ',
    speed: 'Tốc Độ',
    health: 'Sinh Lực',
    attack_percent: '% Tấn Công Cơ Bản',
    defense_percent: '% Phòng Thủ Cơ Bản',
    speed_percent: '% Tốc Độ Cơ Bản',
    health_percent: '% Sinh Lực Cơ Bản',
};

// Chuẩn hóa chuỗi tiếng Việt về không dấu để so khớp nhãn không phân biệt hoa/thường/dấu.
const stripVietnameseDiacritics = (str) => {
    return str.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/gi, (m) => m === 'Đ' ? 'D' : 'd');
};

// Nhãn (không dấu, viết thường) -> key chuẩn dùng trong "Requirements".
const USAGE_CONDITION_LABEL_TO_KEY = {
    'cap do': 'level', 'level': 'level', 'lv': 'level',
    'tan cong': 'atk', 'atk': 'atk', 'attack': 'atk',
    'phong thu': 'def', 'def': 'def', 'defense': 'def',
    'toc do': 'spd', 'spd': 'spd', 'speed': 'spd',
    'hp': 'hp', 'sinh luc': 'hp', 'mau': 'hp', 'health': 'hp',
    'ti le chi mang': 'cr', 'chi mang': 'cr', 'cr': 'cr',
    'sat thuong chi mang': 'cdmg', 'cdmg': 'cdmg',
    'ne tranh': 'evasion', 'evasion': 'evasion',
    'gioi tinh': 'gender', 'gender': 'gender',
};

// Diễn giải ĐÚNG NHỮNG GÌ người chơi đã nhập ở "Điều kiện sử dụng" (dạng "Nhãn: giá trị" tách bằng "|"/","/xuống dòng)
// thành cú pháp "key:value,key:value" của hệ thống — không tự thêm bất kỳ điều kiện nào ngoài những gì đã liệt kê.
const parseUsageConditionToRequirements = (text) => {
    if (!text || typeof text !== 'string' || !text.trim()) return '';
    const segments = text.split(/[|,\n]/).map(s => s.trim()).filter(Boolean);
    const pairs = [];
    for (const segment of segments) {
        let rawLabel, rawValue;
        const idx = segment.indexOf(':');
        if (idx !== -1) {
            rawLabel = segment.slice(0, idx).trim();
            rawValue = segment.slice(idx + 1).trim();
        } else {
            // Chấp nhận luôn dạng không có dấu ":" (VD "level 1", "cấp độ 60") — tách số ở cuối làm giá trị.
            const spaceMatch = segment.match(/^(.+?)\s+(-?\d+(?:\.\d+)?%?)$/);
            if (spaceMatch) {
                rawLabel = spaceMatch[1].trim();
                rawValue = spaceMatch[2].trim();
            }
        }
        if (!rawLabel || !rawValue) continue;
        const normalizedLabel = stripVietnameseDiacritics(rawLabel).toLowerCase().trim();
        const key = USAGE_CONDITION_LABEL_TO_KEY[normalizedLabel];
        if (!key) continue;
        pairs.push(`${key}:${rawValue}`);
    }
    return pairs.join(',');
};

const formatStatString = (statString) => {
    if (!statString || statString === '[Không có]' || statString.trim() === '') return null;

    return statString.split(',')
        .map(pair => {
            const [key, value] = pair.split(':').map(s => s.trim());
            if (!key || !value) return null;

            // Dòng này đã được thay đổi để dùng hằng số toàn cục
            const fullName = STAT_NAME_MAPPINGS[key.toLowerCase()] || (key.charAt(0).toUpperCase() + key.slice(1));
            return `${fullName}: ${value}`;
        })
        .filter(Boolean)
        .join(' | ');
};

const QuantitySelector = ({ data, onConfirm, onCancel }) => {
    const { show, item, title } = data;
    const [quantity, setQuantity] = useState(1);
    const selectorRef = useRef(null);

    useEffect(() => { setQuantity(1); }, [item]);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (selectorRef.current && !selectorRef.current.contains(event.target)) onCancel();
        };
        if (show) document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, [show, onCancel]);

    if (!show || !item) return null;

    const handleQuantityChange = (e) => {
        let value = parseInt(e.target.value, 10);
        if (isNaN(value) || value < 1) value = 1;
        if (value > item.quantity) value = item.quantity;
        setQuantity(value);
    };

    return (
        <div className="fixed inset-0 bg-[#0a0f0a]/80 backdrop-blur-sm flex items-center justify-center z-[140]">
            <div ref={selectorRef} className="bg-[#162216] p-6 shadow-[0_0_30px_rgba(10,20,10,0.9)] w-full max-w-sm border border-[#cda45e]/50 animate-fade-in relative">
                <div className="absolute top-0 left-0 w-3 h-3 border-t-2 border-l-2 border-[#cda45e]"></div>
                <div className="absolute top-0 right-0 w-3 h-3 border-t-2 border-r-2 border-[#cda45e]"></div>
                <div className="absolute bottom-0 left-0 w-3 h-3 border-b-2 border-l-2 border-[#cda45e]"></div>
                <div className="absolute bottom-0 right-0 w-3 h-3 border-b-2 border-r-2 border-[#cda45e]"></div>

                <h4 className="text-lg font-bold text-[#cda45e] mb-1 uppercase tracking-widest border-b border-[#cda45e]/30 pb-2" style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>{title || `Chọn số lượng`}</h4>
                <p className="text-sm font-bold text-[#e8d3a1] mt-3">{item.Name}</p>
                <p className="text-xs text-[#8ba888] mt-1">Tối đa trong túi: {item.quantity}</p>

                <div className="flex items-center justify-center gap-4 my-6">
                    <button onClick={() => setQuantity(q => Math.max(1, q - 1))} className="w-10 h-10 bg-transparent border border-[#8b1515]/50 hover:bg-[#8b1515]/30 text-[#ff4d4d] text-2xl font-bold flex items-center justify-center pb-1">-</button>
                    <input type="number" value={quantity} onChange={handleQuantityChange} min="1" max={item.quantity} className="w-24 p-2 text-center text-xl font-bold font-mono bg-[#0a0f0a] border border-[#cda45e]/40 text-[#e8d3a1] outline-none" />
                    <button onClick={() => setQuantity(q => Math.min(item.quantity, q + 1))} className="w-10 h-10 bg-[#1b2a1b] border border-[#8ba888]/50 hover:border-[#cda45e] text-[#cda45e] text-2xl font-bold flex items-center justify-center pb-1">+</button>
                </div>

                <div className="flex gap-4 mt-6 pt-4 border-t border-[#cda45e]/20">
                    <button onClick={onCancel} className="flex-1 bg-transparent border border-[#8ba888]/40 hover:bg-[#8ba888]/10 hover:border-[#8ba888] text-[#8ba888] font-bold py-2.5 text-xs uppercase tracking-widest transition-colors">Hủy</button>
                    <button onClick={() => onConfirm(item, quantity)} className="flex-1 bg-[#1b2a1b] border border-[#cda45e] hover:bg-[#cda45e]/20 text-[#cda45e] font-bold py-2.5 text-xs uppercase tracking-widest shadow-[inset_0_0_10px_rgba(205,164,94,0.1)] transition-colors">Xác nhận</button>
                </div>
            </div>
        </div>
    );
};

// --- Component Chính: TradeModal (ĐÃ TÁI CẤU TRÚC HOÀN TOÀN) ---
const TradeModal = ({ 
    show, 
    onClose, 
    playerInventory, 
    playerCharacter,
    activeTrade, 
    setActiveTrade, 
    handleConfirmSell,
    handleConfirmBuy,
    gameSettings,
    setModalMessage
}) => {
    if (!show || !activeTrade.trader) return null;

    const [activeView, setActiveView] = useState('sell'); 
    const [quantitySelector, setQuantitySelector] = useState({ show: false, item: null });

    useEffect(() => {
        if(show) {
            setActiveView('sell');
        }
    }, [show]);

    const { finalSellValue, baseSellMultiplier } = useMemo(() => 
        calculateFinalSellValue(activeTrade.playerOffer, activeTrade.sellMultiplier, activeTrade.itemSpecificSellBonuses, gameSettings.difficulty, playerCharacter), 
        [activeTrade, gameSettings.difficulty, playerCharacter]
    );
    
    const finalBuyValue = useMemo(() => {
        if (!activeTrade.npcOffer) return 0;
        return calculateFinalBuyPrice(activeTrade.npcOffer, gameSettings.difficulty, activeTrade.itemSpecificBuyBonuses, playerCharacter);
    }, [activeTrade.npcOffer, activeTrade.itemSpecificBuyBonuses, gameSettings.difficulty, playerCharacter]);

    const handlePlayerItemClick = (item) => {
        if ((item.quantity || 1) > 1) {
            setQuantitySelector({ show: true, item });
        } else {
            addItemToOffer(item, 1);
        }
    };
    
    const addItemToOffer = (item, quantity) => {
        setActiveTrade(prev => {
            const newOffer = [...prev.playerOffer];
            const existingItemIndex = newOffer.findIndex(offerItem => offerItem.id === item.id);

            if (existingItemIndex > -1) {
                newOffer[existingItemIndex].quantity += quantity;
            } else {
                newOffer.push({ ...item, quantity });
            }
            
            return { 
                ...prev, 
                playerOffer: newOffer, 
                offerType: 'sell',
                npcOffer: null
            };
        });
        setQuantitySelector({ show: false, item: null });
    };

    const playerWantsToBuy = (item) => {
        setActiveTrade(prev => ({ 
            ...prev, 
            npcOffer: item, 
            playerOffer: [],
            offerType: 'buy',
        }));
    };
    
    const removeItemFromOffer = (itemId) => {
        setActiveTrade(prev => {
            const newOffer = prev.playerOffer.filter(item => item.id !== itemId);
            const newSpecificBonuses = { ...prev.itemSpecificSellBonuses };
            const removedItem = prev.playerOffer.find(item => item.id === itemId);
            if (removedItem) {
                delete newSpecificBonuses[removedItem.Name];
            }

            return {
                ...prev,
                playerOffer: newOffer,
                itemSpecificSellBonuses: newSpecificBonuses
            };
        });
    };
    
    const playerOfferIDs = new Set(activeTrade.playerOffer.map(item => item.id));
    const sellableInventory = playerInventory.filter(invItem => !playerOfferIDs.has(invItem.id));

    const Panel = ({ title, titleColor, children }) => (
        <div className="flex flex-col bg-[#0a0f0a] border border-[#cda45e]/20 p-4 h-full min-h-0 relative">
            <h3 className={`text-sm font-bold uppercase tracking-widest ${titleColor} mb-4 flex-shrink-0`} style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>{title}</h3>
            <div className="flex-grow overflow-y-auto space-y-2.5 pr-2 custom-scrollbar-gold">
                {children}
            </div>
        </div>
    );

    const renderBuyInfo = () => {
        if (activeView !== 'buy' || !activeTrade.npcOffer) return null;

        const difficultyMultipliers = DIFFICULTY_MULTIPLIERS[gameSettings.difficulty] || DIFFICULTY_MULTIPLIERS['Thường'];
        let baseBuyMultiplier = difficultyMultipliers.buy;
        let totalReductionPercent = 0;
        if (playerCharacter) {
            const equippedSkills = Object.values(playerCharacter.equippedSkills || {}).filter(Boolean);
            equippedSkills.forEach(skill => {
                (skill.passive_effects || []).forEach(effect => {
                    if (effect.type === 'DECREASE_BUY_PRICE_MODIFIER') {
                        totalReductionPercent += effect.value;
                    }
                });
            });
            baseBuyMultiplier -= (totalReductionPercent / 100.0);
        }
        baseBuyMultiplier = Math.max(0, baseBuyMultiplier);

        const negotiationMultiplier = activeTrade.itemSpecificBuyBonuses?.[activeTrade.npcOffer.Name] !== undefined 
            ? activeTrade.itemSpecificBuyBonuses[activeTrade.npcOffer.Name] 
            : 1;
        const negotiationPercentage = Math.round(negotiationMultiplier * 100);

        let negotiationColorClass = 'text-yellow-500';
        if (negotiationPercentage < 100) negotiationColorClass = 'text-emerald-400';
        if (negotiationPercentage > 100) negotiationColorClass = 'text-rose-400';

        return (
            <div className="text-[10px] uppercase font-mono tracking-wider mt-1.5 space-y-0.5">
                <p className="text-[#8ba888]">(Hệ số Mua gốc: {Math.round(baseBuyMultiplier * 100)}%)</p>
                <p className={negotiationColorClass}>(Tỷ lệ thương lượng: {negotiationPercentage}%)</p>
            </div>
        );
    };

    return (
        <div className="fixed inset-0 bg-[#0a0f0a]/90 backdrop-blur-sm flex items-center justify-center p-2 sm:p-4 z-50 animate-fade-in">
            <div className="bg-[#162216] p-4 sm:p-6 shadow-[0_0_50px_rgba(10,20,10,1)] w-full max-w-5xl h-[95vh] sm:h-[90vh] flex flex-col border border-[#cda45e]/50 relative">
                
                <div className="absolute top-0 left-0 w-4 h-4 border-t-2 border-l-2 border-[#cda45e] pointer-events-none"></div>
                <div className="absolute top-0 right-0 w-4 h-4 border-t-2 border-r-2 border-[#cda45e] pointer-events-none"></div>
                <div className="absolute bottom-0 left-0 w-4 h-4 border-b-2 border-l-2 border-[#cda45e] pointer-events-none"></div>
                <div className="absolute bottom-0 right-0 w-4 h-4 border-b-2 border-r-2 border-[#cda45e]/50 pointer-events-none"></div>

                <div className="flex justify-between items-center mb-4 pb-3 border-b border-[#cda45e]/20 flex-shrink-0">
                    <div className="flex items-center gap-4 flex-wrap">
                         <h2 className="text-xl sm:text-2xl font-bold text-[#cda45e] uppercase tracking-widest" style={{ fontFamily: "'Noto Serif Vietnamese', serif", textShadow: '0 0 10px rgba(205,164,94,0.3)' }}>Giao Dịch với {activeTrade.trader.Name}</h2>
                         <div className="bg-[#0a0f0a] border border-[#cda45e]/30 px-3 py-1.5 text-xs flex items-center gap-2 rounded-sm shadow-inner">
                            <CircleStackIcon className="w-5 h-5 text-[#cda45e]"/>
                            <span className="font-bold text-[#e8d3a1] font-mono">{playerCharacter?.currency || 0}</span>
                            <span className="text-[#8ba888] uppercase tracking-wider text-[10px] font-semibold">{gameSettings.currencyName}</span>
                         </div>
                    </div>
                    <div className="flex items-center gap-3">
                         <div className="flex bg-[#0a0f0a] border border-[#cda45e]/30 p-0.5 rounded-sm">
                             <button onClick={() => setActiveView('sell')} className={`px-4 py-1.5 text-xs font-bold tracking-widest uppercase transition-colors rounded-sm ${activeView === 'sell' ? 'bg-[#cda45e]/20 text-[#e8d3a1] border border-[#cda45e]/40' : 'text-[#8ba888] hover:text-[#cda45e]'}`}>Bán Đồ</button>
                             <button onClick={() => setActiveView('buy')} className={`px-4 py-1.5 text-xs font-bold tracking-widest uppercase transition-colors rounded-sm ${activeView === 'buy' ? 'bg-[#cda45e]/20 text-[#e8d3a1] border border-[#cda45e]/40' : 'text-[#8ba888] hover:text-[#cda45e]'}`}>Mua Đồ</button>
                         </div>
                         <button onClick={onClose} className="text-[#a3b8a3] hover:text-[#e8d3a1] text-3xl font-semibold leading-none flex items-center justify-center" style={{ minWidth: TOUCH_TARGET_MIN + 'px', minHeight: TOUCH_TARGET_MIN + 'px' }}>&times;</button>
                    </div>
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 flex-grow overflow-hidden min-h-0 pb-2">
                    <Panel title={activeView === 'sell' ? "Hành Trang Của Ngươi" : `Hàng Hóa của ${activeTrade.trader.Name}`} titleColor={activeView === 'sell' ? "text-[#a5b4fc]" : "text-[#5eead4]"}>
                        {activeView === 'sell' ? (
                            sellableInventory.length > 0 ? (
                                sellableInventory.map(item => (
                                    <button key={item.id} onClick={() => handlePlayerItemClick(item)} className="w-full text-left p-3 bg-[#0a0f0a] border border-[#cda45e]/20 hover:border-[#cda45e] hover:bg-[#1b2a1b]/40 transition-colors rounded-sm shadow-sm group">
                                        <div className="flex justify-between items-center">
                                            <p className={`font-bold tracking-wide ${getItemRarityColor(item)}`} style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>{item.Name}</p>
                                            {(item.quantity || 1) > 1 && <span className="text-xs text-[#8ba888] font-mono">x{item.quantity}</span>}
                                        </div>
                                        <p className="text-xs text-[#cda45e] font-mono mt-1.5">Giá trị gốc: {item.Value || '??'}</p>
                                    </button>
                                ))
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-[#8ba888] opacity-60 py-10">
                                    <BackpackIcon className="w-10 h-10 mb-2"/>
                                    <p className="italic text-sm">Hành trang trống.</p>
                                </div>
                            )
                        ) : (
                            (activeTrade.traderWares || []).length > 0 ? (
                                activeTrade.traderWares.map(item => (
                                    <button key={item.id} onClick={() => playerWantsToBuy(item)} className="w-full text-left p-3 bg-[#0a0f0a] border border-[#cda45e]/20 hover:border-[#cda45e] hover:bg-[#1b2a1b]/40 transition-colors rounded-sm shadow-sm group">
                                         <p className={`font-bold tracking-wide ${getItemRarityColor(item)}`} style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>{item.Name}</p>
                                         <p className="text-xs text-[#cda45e] font-mono mt-1.5">Giá mua: {calculateFinalBuyPrice(item, gameSettings.difficulty, activeTrade.itemSpecificBuyBonuses, playerCharacter) || '??'}</p>
                                    </button>
                                ))
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center p-6 bg-[#0a0f0a]/30 border border-dashed border-[#cda45e]/20 rounded-sm py-12">
                                     <InformationCircleIcon className="w-8 h-8 text-[#cda45e] mb-3" />
                                     <p className="text-[#8ba888] italic text-sm text-center">Không có gì để bán.</p>
                                     <div className="text-[#e8d3a1] text-xs mt-4 bg-[#1b2a1b] p-3 border border-[#cda45e]/30 max-w-xs leading-relaxed rounded-sm">
                                         <strong>Mẹo:</strong> Hỏi đối phương xem có bán món gì không để họ trưng hàng ra.
                                     </div>
                                </div>
                            )
                        )}
                    </Panel>

                    <div className="flex flex-col bg-[#101a10] border-2 border-dashed border-[#cda45e]/40 p-4 h-full relative shadow-[inset_0_0_20px_rgba(205,164,94,0.05)]">
                        <h3 className="text-sm font-bold text-[#cda45e] mb-3 text-center flex-shrink-0 uppercase tracking-widest font-ngoc-an">Bàn Đàm Phán</h3>
                        
                        <div className="flex-grow bg-[#0a0f0a] border border-[#cda45e]/20 p-3 rounded-none space-y-3 overflow-y-auto scrollbar-thin scrollbar-thumb-[#cda45e] scrollbar-track-transparent min-h-0 shadow-inner">
                            {activeView === 'sell' && activeTrade.playerOffer.length > 0 ? (
                                <>
                                    {activeTrade.playerOffer.map(item => {
                                        const specificMultiplier = activeTrade.itemSpecificSellBonuses[item.Name];
                                        const finalMultiplier = specificMultiplier !== undefined ? specificMultiplier : (activeTrade.sellMultiplier || 0);
                                        
                                        let multiplierColor = 'text-yellow-500';
                                        if (finalMultiplier > 1) multiplierColor = 'text-emerald-400';
                                        if (finalMultiplier > 0 && finalMultiplier < 1) multiplierColor = 'text-orange-400';
                                        if (finalMultiplier <= 0.7 && finalMultiplier > 0) multiplierColor = 'text-rose-400';

                                        return (
                                            <div key={item.id} className="flex justify-between items-center bg-[#162216] border border-[#cda45e]/15 p-3 rounded-sm animate-fade-in shadow-sm">
                                                <div>
                                                    <p className={`text-sm font-bold tracking-wide ${getItemRarityColor(item)}`} style={{ fontFamily: "'Noto Serif Vietnamese', serif" }}>{item.Name}</p>
                                                    <p className="text-xs text-[#8ba888] font-mono mt-0.5">Số lượng: {item.quantity}</p>
                                                    <p className={`text-xs font-bold font-mono uppercase mt-1 ${multiplierColor}`}>
                                                        Hệ số kỳ vọng: {Math.round(finalMultiplier * 100)}%
                                                    </p>
                                                </div>
                                                <button onClick={() => removeItemFromOffer(item.id)} className="text-rose-400 hover:text-rose-200 transition-colors p-1" title="Bỏ khỏi bàn đàm phán"><XMarkIcon className="w-6 h-6"/></button>
                                            </div>
                                        );
                                    })}
                                </>
                            ) : activeView === 'buy' && activeTrade.npcOffer ? (
                                <div className="animate-fade-in h-full"><ItemDetailsPanel item={activeTrade.npcOffer} isEmbedded={true} /></div>
                            ) : (
                                <div className="flex flex-col items-center justify-center h-full text-[#8ba888] opacity-60 py-12">
                                    <InformationCircleIcon className="w-10 h-10 mb-2 text-[#cda45e]"/>
                                    <p className="italic text-sm">Chọn vật phẩm để giao dịch.</p>
                                </div>
                            )}
                        </div>

                        <div className="mt-4 pt-3 border-t border-[#cda45e]/20 text-center flex-shrink-0">
                            {activeView === 'sell' && activeTrade.playerOffer.length > 0 ? (
                                <>
                                    <h4 className="text-xs font-bold text-[#8ba888] uppercase tracking-widest mb-1">Sẽ Thu Về</h4>
                                    <p className="text-3xl font-extrabold text-[#cda45e] font-mono">{finalSellValue} <span className="text-xs text-[#8ba888]">{gameSettings.currencyName}</span></p>
                                    <p className="text-[10px] text-[#8ba888] font-mono uppercase tracking-widest mt-1">(Tỉ lệ thu mua cố định: {Math.round(baseSellMultiplier * 100)}%)</p>
                                    <button onClick={handleConfirmSell} className="mt-3 w-full bg-[#1b2a1b] border border-[#cda45e] hover:bg-[#cda45e]/20 text-[#cda45e] font-bold py-3 uppercase tracking-widest text-xs shadow-[inset_0_0_15px_rgba(205,164,94,0.1)] transition-all">Bán Toàn Bộ</button>
                                </>
                            ) : activeView === 'buy' && activeTrade.npcOffer ? (
                                <>
                                    <h4 className="text-xs font-bold text-[#8ba888] uppercase tracking-widest mb-1">Cần Thanh Toán</h4>
                                    <p className="text-3xl font-extrabold text-rose-500 font-mono">{finalBuyValue} <span className="text-xs text-[#8ba888]">{gameSettings.currencyName}</span></p>
                                    {renderBuyInfo()}
                                    <button onClick={() => handleConfirmBuy(activeTrade.npcOffer, finalBuyValue)} className="mt-3 w-full bg-[#1b2a1b] border border-[#cda45e] hover:bg-[#cda45e]/20 text-[#cda45e] font-bold py-3 uppercase tracking-widest text-xs shadow-[inset_0_0_15px_rgba(205,164,94,0.1)] transition-all">Mua Vật Phẩm</button>
                                </>
                            ) : null}
                        </div>
                    </div>
                </div>

                <QuantitySelector 
                    data={quantitySelector} 
                    onConfirm={addItemToOffer} 
                    onCancel={() => setQuantitySelector({ show: false, item: null })} 
                />
            </div>
        </div>
    );
};

