// --- CẤU HÌNH LƯU TRỮ QUA GITHUB (dùng cho "Lưu Ngay" — đồng bộ đa thiết bị) ---
// Token PHẢI được đặt trong .env.local (VITE_GITHUB_TOKEN) — KHÔNG BAO GIỜ hardcode/commit token vào source code.
const GITHUB_SAVE_REPO = import.meta.env.VITE_GITHUB_REPO || 'Lavie2404/textbase';
/**
 * The key used when the player has not supplied one (`apiMode === 'defaultGemini'`).
 *
 * Empty in a build that ships no platform key - `requestAi` then fails fast with
 * `config_error` instead of walking the whole model ladder against an endpoint
 * that cannot authenticate (code review C-3). The user-facing message stays the
 * existing Vietnamese auth error below.
 */
const PLATFORM_DEFAULT_GEMINI_KEY = (import.meta.env && import.meta.env.VITE_GEMINI_API_KEY) || '';
/**
 * Spare Gemini keys (project decision 2026-08-28: main key + two spares). Read
 * from `VITE_GEMINI_API_KEY_FALLBACKS` in the gitignored `.env.local` (or the CI
 * secret of the same name), comma-separated - NEVER a literal in source
 * (technical-preferences.md "Forbidden Patterns"). Every Gemini call tries the
 * active key first and rolls over to these, in order, when a key answers 429
 * (quota) or is rejected as invalid; text calls do it inside `requestAi`, image
 * calls through `fetchGeminiWithKeyFallback` below.
 */
const PLATFORM_FALLBACK_GEMINI_KEYS = parseKeyList(import.meta.env && import.meta.env.VITE_GEMINI_API_KEY_FALLBACKS);
const GITHUB_SAVE_TOKEN = import.meta.env.VITE_GITHUB_TOKEN || '';
const GITHUB_SAVES_DIR = 'saves';
const GITHUB_SAVE_SLOT_COUNT = 5;
const GITHUB_INDEX_PATH = `${GITHUB_SAVES_DIR}/index.json`;

const githubApiFetch = async (urlPath, options = {}) => {
    if (!GITHUB_SAVE_TOKEN) {
        throw new Error('Chưa cấu hình VITE_GITHUB_TOKEN trong .env.local. Vui lòng tạo Personal Access Token (quyền "Contents: Read and write") cho repo và điền vào .env.local rồi khởi động lại.');
    }
    return fetch(`https://api.github.com/repos/${GITHUB_SAVE_REPO}/${urlPath}`, {
        ...options,
        headers: {
            'Authorization': `Bearer ${GITHUB_SAVE_TOKEN}`,
            'Accept': 'application/vnd.github+json',
            ...(options.headers || {})
        }
    });
};

const githubSaveApiFetch = async (path, options = {}) => githubApiFetch(`contents/${path}`, options);

// Đọc 1 file JSON trên GitHub. Trả về { data, sha } hoặc null nếu file chưa tồn tại (404).
const getGithubJsonFile = async (path) => {
    const res = await githubSaveApiFetch(path);
    if (res.status === 404) return null;
    if (!res.ok) throw new Error(`Lỗi đọc file GitHub "${path}": HTTP ${res.status}`);
    const json = await res.json();
    let rawContent = json.content;
    // Contents API chỉ trả nội dung inline cho file ≤ 1MB (file save có avatar base64 dễ vượt mốc này).
    // Với file lớn hơn, encoding trả về "none" và content rỗng -> phải lấy qua Git Blobs API (hỗ trợ tới 100MB).
    if (json.encoding !== 'base64' || !rawContent) {
        const blobRes = await githubApiFetch(`git/blobs/${json.sha}`);
        if (!blobRes.ok) throw new Error(`Lỗi đọc file GitHub "${path}" (blob): HTTP ${blobRes.status}`);
        const blobJson = await blobRes.json();
        rawContent = blobJson.content;
    }
    const decoded = decodeURIComponent(escape(atob(rawContent.replace(/\n/g, ''))));
    return { data: JSON.parse(decoded), sha: json.sha };
};

// Ghi (tạo mới hoặc cập nhật) 1 file JSON trên GitHub. Truyền existingSha khi cập nhật file đã tồn tại.
const putGithubJsonFile = async (path, dataObj, message, existingSha = undefined) => {
    const jsonStr = JSON.stringify(dataObj, null, 2);
    const base64Content = btoa(unescape(encodeURIComponent(jsonStr)));
    const res = await githubSaveApiFetch(path, {
        method: 'PUT',
        body: JSON.stringify({
            message,
            content: base64Content,
            ...(existingSha ? { sha: existingSha } : {})
        })
    });
    if (!res.ok) {
        const errText = await res.text();
        throw new Error(`Lỗi ghi file GitHub "${path}": HTTP ${res.status} - ${errText}`);
    }
    return res.json();
};

// Xóa 1 file JSON trên GitHub (cần đúng sha hiện tại của file).
const deleteGithubJsonFile = async (path, sha, message) => {
    const res = await githubSaveApiFetch(path, {
        method: 'DELETE',
        body: JSON.stringify({ message, sha })
    });
    if (!res.ok) {
        const errText = await res.text();
        throw new Error(`Lỗi xóa file GitHub "${path}": HTTP ${res.status} - ${errText}`);
    }
    return res.json();
};

// Đọc bảng chỉ mục 5 slot lưu trên GitHub (tự chuẩn hóa về đúng 5 phần tử, điền null cho slot trống).
const getGithubSaveIndex = async () => {
    const result = await getGithubJsonFile(GITHUB_INDEX_PATH);
    if (!result) return { slots: new Array(GITHUB_SAVE_SLOT_COUNT).fill(null), sha: null };
    const slots = [...(result.data.slots || [])];
    while (slots.length < GITHUB_SAVE_SLOT_COUNT) slots.push(null);
    return { slots: slots.slice(0, GITHUB_SAVE_SLOT_COUNT), sha: result.sha };
};

// 1. Hàm gọi lấy khóa ImgBB bảo mật được giấu trên Supabase
const fetchImgbbKeyFromCloud = async () => {
    try {
        const response = await fetch(`${SUPABASE_URL}/rest/v1/system_config?config_name=eq.imgbb_key&select=config_value`, {
            method: 'GET',
            headers: {
                'apikey': SUPABASE_ANON_KEY,
                'Authorization': `Bearer ${SUPABASE_ANON_KEY}`
            }
        });
        if (!response.ok) {
            throw new Error('Không thể tải cấu hình khóa bảo mật từ Supabase.');
        }
        const data = await response.json();
        if (data && data.length > 0) {
            return data[0].config_value; // Trả về khóa ImgBB dạng chữ thô ở bộ nhớ tạm RAM
        }
        throw new Error('Không tìm thấy khóa cấu hình tương ứng.');
    } catch (error) {
        console.error("Lỗi fetchImgbbKeyFromCloud:", error);
        throw error;
    }
};

// 2. Hàm tải ảnh Base64 lên ImgBB sử dụng khóa lấy động bảo mật
const uploadImageToImgBB = async (imageBase64) => {
    if (!imageBase64 || !imageBase64.startsWith('data:image')) {
        return imageBase64;
    }
    try {
        // Lấy khóa động từ Supabase, khóa này chỉ tồn tại trên RAM, người xem code Canvas sẽ không nhìn thấy
        const activeApiKey = await fetchImgbbKeyFromCloud();

        const cleanBase64 = imageBase64.replace(/^data:image\/\w+;base64,/, "");
        const formData = new URLSearchParams();
        formData.append('image', cleanBase64);

        const response = await fetch(`https://api.imgbb.com/1/upload?key=${activeApiKey}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: formData
        });

        const result = await response.json();
        if (response.ok && result.success) {
            return result.data.url;
        }
        throw new Error(result.error?.message || 'Lỗi tải ảnh lên ImgBB');
    } catch (error) {
        console.error("Lỗi uploadImageToImgBB:", error);
        throw error;
    }
};

// 3. Hàm kiểm tra tính hợp lệ của mã khóa VIP
const verifyVipKeyInCloud = async (keyCode) => {
    if (!keyCode) return null;
    try {
        const response = await fetch(`${SUPABASE_URL}/rest/v1/vip_keys?key_code=ilike.${keyCode.trim()}&select=key_code,status,owner_name`, {
            method: 'GET',
            headers: {
                'apikey': SUPABASE_ANON_KEY,
                'Authorization': `Bearer ${SUPABASE_ANON_KEY}`
            }
        });

        if (!response.ok) {
            throw new Error('Không thể kết nối máy chủ Supabase.');
        }

        const data = await response.json();
        if (!data || data.length === 0) {
            throw new Error('Mã khóa VIP không tồn tại.');
        }

        const keyInfo = data[0];
        if (!keyInfo.status) {
            throw new Error('Mã khóa VIP này đã bị tạm khóa.');
        }

        return {
            isValid: true,
            keyCode: keyInfo.key_code,
            ownerName: keyInfo.owner_name
        };
    } catch (error) {
        console.error("Lỗi verifyVipKeyInCloud:", error);
        throw error;
    }
};

const loadSavesFromCloud = async (keyCode) => {
    try {
        const keyCheck = await verifyVipKeyInCloud(keyCode);
        const canonicalKey = keyCheck.keyCode.trim(); 
        const response = await fetch(`${SUPABASE_URL}/rest/v1/saves?vip_key=eq.${canonicalKey}&select=id,slot_number,metadata,updated_at&order=slot_number.asc`, {
            method: 'GET',
            headers: {
                'apikey': SUPABASE_ANON_KEY,
                'Authorization': `Bearer ${SUPABASE_ANON_KEY}`
            }
        });

        if (!response.ok) {
            const errBody = await response.text();
            console.error("🚨 [LỖI CHI TIẾT SUPABASE]:", errBody);
            throw new Error(`Không thể tải tệp lưu từ máy chủ. Chi tiết lỗi: ${errBody}`);
        }

        const saves = await response.json();
        
        for (const save of saves) {
            if (!save.metadata) {
                console.log(`[Cloud Fallback] Slot ${save.slot_number} lacks metadata. Fetching game_data...`);
                const singleResponse = await fetch(`${SUPABASE_URL}/rest/v1/saves?id=eq.${save.id}&select=game_data`, {
                    method: 'GET',
                    headers: {
                        'apikey': SUPABASE_ANON_KEY,
                        'Authorization': `Bearer ${SUPABASE_ANON_KEY}`
                    }
                });
                if (singleResponse.ok) {
                    const singleData = await singleResponse.json();
                    if (singleData && singleData[0]) {
                        save.game_data = singleData[0].game_data;
                    }
                }
            }
        }
        return saves;
    } catch (error) {
        console.error("Lỗi loadSavesFromCloud:", error);
        throw error;
    }
};

const saveGameToCloudDb = async (keyCode, slotNumber, gameData, metadata = null) => {
    try {
        const keyCheck = await verifyVipKeyInCloud(keyCode);
        const canonicalKey = keyCheck.keyCode.trim();

        const checkResponse = await fetch(`${SUPABASE_URL}/rest/v1/saves?vip_key=eq.${canonicalKey}&slot_number=eq.${slotNumber}&select=id`, {
            method: 'GET',
            headers: {
                'apikey': SUPABASE_ANON_KEY,
                'Authorization': `Bearer ${SUPABASE_ANON_KEY}`
            }
        });

        if (!checkResponse.ok) {
            const checkErr = await checkResponse.text();
            console.error("🚨 [LỖI TRUY VẤN KIỂM TRA LƯU]:", checkErr);
            throw new Error(`Kiểm tra tệp lưu thất bại: ${checkErr}`);
        }

        const existingRecords = await checkResponse.json();
        let saveResponse;

        if (existingRecords && existingRecords.length > 0) {
            const recordId = existingRecords[0].id;
            saveResponse = await fetch(`${SUPABASE_URL}/rest/v1/saves?id=eq.${recordId}`, {
                method: 'PATCH',
                headers: {
                    'apikey': SUPABASE_ANON_KEY,
                    'Authorization': `Bearer ${SUPABASE_ANON_KEY}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    game_data: gameData,
                    metadata: metadata,
                    updated_at: new Date().toISOString()
                })
            });
        } else {
            saveResponse = await fetch(`${SUPABASE_URL}/rest/v1/saves`, {
                method: 'POST',
                headers: {
                    'apikey': SUPABASE_ANON_KEY,
                    'Authorization': `Bearer ${SUPABASE_ANON_KEY}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    vip_key: canonicalKey,
                    slot_number: slotNumber,
                    game_data: gameData,
                    metadata: metadata,
                    updated_at: new Date().toISOString()
                })
            });
        }

        if (!saveResponse.ok) {
            const errText = await saveResponse.text();
            console.error("🚨 [LỖI ĐỒNG BỘ CHI TIẾT]:", errText);
            throw new Error(`Không thể đồng bộ tệp lưu lên cơ sở dữ liệu. Chi tiết từ máy chủ: ${errText}`);
        }

        return true;
    } catch (error) {
        console.error("Lỗi saveGameToCloudDb:", error);
        throw error;
    }
};

const fetchFullSaveFromCloud = async (rowId) => {
    const response = await fetch(`${SUPABASE_URL}/rest/v1/saves?id=eq.${rowId}&select=game_data`, {
        method: 'GET',
        headers: {
            'apikey': SUPABASE_ANON_KEY,
            'Authorization': `Bearer ${SUPABASE_ANON_KEY}`
        }
    });
    if (!response.ok) {
        throw new Error("Không thể tải tệp lưu chi tiết từ máy chủ đám mây.");
    }
    const data = await response.json();
    if (data && data[0]) {
        return data[0].game_data;
    }
    throw new Error("Không tìm thấy dữ liệu tệp lưu.");
};

