// 1. Hàm xác thực khóa VIP và nạp bản lưu từ Supabase
const handleVerifyVipKey = async (keyCodeInput, isFromInGame = false) => {
    const cleanKey = (keyCodeInput || '').trim();
    if (!cleanKey) return;
    
    setIsVerifyingVip(true);
    try {
        const check = await verifyVipKeyInCloud(cleanKey);
        if (check && check.isValid) {
            setCloudVipKey(check.keyCode.trim());
            setIsValidatedVip(true);
            
            const cloudSaves = await loadSavesFromCloud(cleanKey);
            
            const formattedSaves = cloudSaves.map(save => {
                try {
                    let parsed = null;
                    if (save.metadata) {
                        parsed = typeof save.metadata === 'string' ? JSON.parse(save.metadata) : save.metadata;
                    } else if (save.game_data) {
                        const decompressed = window.LZString.decompressFromUTF16(save.game_data) || atob(save.game_data);
                        parsed = JSON.parse(decompressed);
                    }
                    
                    return {
                        id: `manual_${save.slot_number}_supabase`,
                        isSupabaseCloud: true,
                        supabaseRowId: save.id, 
                        ...parsed,
                        updatedAt: { toDate: () => new Date(save.updated_at) }
                    };
                } catch (e) {
                    return null;
                }
            }).filter(Boolean);
            setSavedGames(prev => {
                const filtered = prev.filter(g => !g.isSupabaseCloud);
                const merged = [...formattedSaves, ...filtered];
                merged.sort((a, b) => {
                    const timeA = a.updatedAt?.toDate ? a.updatedAt.toDate().getTime() : 0;
                    const timeB = b.updatedAt?.toDate ? b.updatedAt.toDate().getTime() : 0;
                    return timeB - timeA;
                });
                return merged;
            });

            if (isFromInGame) {
                setShowVipInputModal(false); 
                setShowSaveSlotModal(true);  
            }
            setVipOwnerName(check.ownerName || 'Ký Chủ');
            setShowVipWelcomeModal(true);
        }
    } catch (err) {
        setModalMessage({ show: true, title: "Kích Hoạt Thất Bại", content: err.message, type: "error" });
    } finally {
        setIsVerifyingVip(false);
    }
};

