const justLoadedRef = useRef(false);
const pvpRoomRef = useRef(null);
useEffect(() => {
      const handleEmergencyExit = (e) => {
          const room = pvpRoomRef.current;
          if (room?.id) {
              const roomRef = doc(pvpDb, `pvp_rooms/${room.id}`);
              if (room.isCombatStarted) {
                  updateDoc(roomRef, { status: 'abandoned', abandonedBy: room.role }).catch(()=>{});
              } else if (room.role === 'host') {
                  deleteDoc(roomRef).catch(()=>{});
              } else {
                  updateDoc(roomRef, { status: 'waiting', guest: null, guestReady: false }).catch(()=>{});
              }
          }
          clearAllIndexedDB();
      };

      window.addEventListener('beforeunload', handleEmergencyExit);
      window.addEventListener('unload', handleEmergencyExit);

      return () => {
          window.removeEventListener('beforeunload', handleEmergencyExit);
          window.removeEventListener('unload', handleEmergencyExit);
      };
  }, []);
const activeCombatLoopRef = useRef(null);
useEffect(() => {
    activeCombatLoopRef.current = activeCombatLoop;
    }, [activeCombatLoop]);
const [generatingAvatars, setGeneratingAvatars] = useState({}); 
const [generatingSprites, setGeneratingSprites] = useState({});     
const handleTargetSelection = (targetId) => {
    setIsProcessingAction(true);
    setPvpTurnTimeLeft(null);
    const { skill, casterId, flavorText, companionCommand } = combatTargetingState;
    
    setCombatTargetingState({ isActive: false, skill: null, casterId: null });
    setCombatUIState({ view: 'main', items: [] }); 

    setTimeout(async () => {
        if (!activeCombatLoop || !skill || !casterId) {
            console.error("Lỗi handleTargetSelection: Trạng thái chiến đấu không hợp lệ.");
            setIsProcessingAction(false);
            return;
        }

        const turnTaker = activeCombatLoop.currentTurnTaker;
        if (!turnTaker || turnTaker.id !== casterId) {
            console.warn("Lỗi: Yêu cầu chọn mục tiêu không khớp với người đang hành động.");
            setIsProcessingAction(false);
            return;
        }

        const target = activeCombatLoop.allCombatants.find(c => c.id === targetId);
        if (!target) {
            console.error("Lỗi: Không tìm thấy mục tiêu đã chọn.");
            setIsProcessingAction(false);
            return;
        }

        if (companionCommand) {
            activeCombatLoop.setNextCompanionCommand(companionCommand);
        }
        await handleActionRequest(turnTaker, false, { skillToUse: skill, target: target, isContinuation: true, flavorText: flavorText }, activeCombatLoop);
    }, 0);
};

