const checkForOverloadDrop = useCallback(() => {
    if (gameMode !== 'EXPLORATION') return;

    setknowledge(prevKnowledge => {
        const player = prevKnowledge.characters.find(c => c.isPlayer);
        if (!player) return prevKnowledge;

        const currentWeight = calculateCurrentWeight(player.inventory);
        const maxWeight = calculateMaxCarryWeight(player);

        if (currentWeight > maxWeight && maxWeight > 0 && player.inventory.length > 0) {
            const dropChance = 2 * (currentWeight - maxWeight) / maxWeight;
            
            if (Math.random() < dropChance) {
                // Tạo một bản sao sâu để tránh mutate state
                const newKnowledge = JSON.parse(JSON.stringify(prevKnowledge));
                const playerToUpdate = newKnowledge.characters.find(c => c.isPlayer);
                
                const randomIndex = Math.floor(Math.random() * playerToUpdate.inventory.length);
                const itemToDrop = playerToUpdate.inventory[randomIndex];
                
                // Xóa toàn bộ stack vật phẩm khỏi hành trang
                playerToUpdate.inventory.splice(randomIndex, 1);
                
                // Tạo thông báo và cập nhật storyHistory
                const message = `**[Hệ thống]** Vì mang vác quá nặng, ngươi đã vô tình đánh rơi ${itemToDrop.quantity > 1 ? itemToDrop.quantity + ' x ' : ''}${itemToDrop.Name}!`;
                setStoryHistory(prevHistory => [...prevHistory, { id: crypto.randomUUID(), type: 'system', content: message, transient: true }]);
                
                return newKnowledge; // Trả về knowledge đã được cập nhật
            }
        }
        
        return prevKnowledge; 
    });
}, [gameMode, setknowledge, setStoryHistory]); // <-- THAY ĐỔI CỐT LÕI NẰM Ở ĐÂY

useEffect(() => {
    if (adventureTurnCount > 0 && adventureTurnCount % 2 === 0) {
        console.log(`Lượt phiêu lưu thứ ${adventureTurnCount}, tiến hành kiểm tra quá tải.`);
        checkForOverloadDrop();
    }
}, [adventureTurnCount, checkForOverloadDrop]);
const autoAppraisedRefs = useRef(new Set());

useEffect(() => {
    if (isProcessingAction || isLoading) return;

    const companionsInNeed = knowledge.characters.filter(c => 
        c.isCompanion === true && 
        !c.isPermanentlyDead && 
        !c.isCompanionSetupDone && // KHÓA CHỐNG LẶP: Đã cài đặt xong thì dù có 0 kỹ năng cũng không tạo lại
        !autoAppraisedRefs.current.has(c.id)
    );

    if (companionsInNeed.length > 0) {
        const npc = companionsInNeed[0];
        autoAppraisedRefs.current.add(npc.id);

        const setupCompanion = async () => {
            try {
                const effectiveApiKey = apiMode === 'userKey' ? apiKey : "";
                if (apiMode === 'userKey' && !effectiveApiKey) return;

                const playerLvl = knowledge.characters.find(c => c.isPlayer)?.level || 1;
                let detailedNpcProfile = null;

                if (!npc.isAppraised) {
                    detailedNpcProfile = await fetchNpcDetailsFromAI(npc, gameSettings, effectiveApiKey, playerLvl);
                }

                const hasNoSkills = !npc.skills || npc.skills.length === 0 || !(npc.learnedSkills || []).some(s => s.skillType === 'combat');
                let generatedSkill = null;

                if (hasNoSkills) {
                    const determinedRarity = getFinalRarityByLevel(npc.level || playerLvl);
                    const skillIdea = await generateNpcSkillIdea(npc, determinedRarity, effectiveApiKey);
                    if (skillIdea) {
                        const isUltimate = Math.random() < 0.25; // 75% cơ bản - 25% tối thượng
                        const preliminaryDetails = { 
                            skillType: 'combat', 
                            skillCategory: isUltimate ? 'ultimate' : 'basic' 
                        };
                        const detailedSkillIdea = { ...skillIdea, ...preliminaryDetails, rarity: determinedRarity };
                        generatedSkill = await fetchSkillDetailsFromAI(detailedSkillIdea, gameSettings, effectiveApiKey);
                    }
                }

                setknowledge(prev => {
                    const newKnowledge = JSON.parse(JSON.stringify(prev));
                    const charIndex = newKnowledge.characters.findIndex(c => c.id === npc.id);
                    
                    if (charIndex > -1) {
                        let charToUpdate = newKnowledge.characters[charIndex];
                        charToUpdate.isCompanionSetupDone = true; // Đánh dấu đã hoàn thành thiết lập ban đầu
                        
                        if (detailedNpcProfile) {
                            charToUpdate.Role = detailedNpcProfile.Role;
                            charToUpdate.Appearance = detailedNpcProfile.Appearance;
                            charToUpdate.Backstory = detailedNpcProfile.Backstory;
                            charToUpdate.Personality = detailedNpcProfile.Personality;
                            charToUpdate.Stance = detailedNpcProfile.Stance;
                            if (String(detailedNpcProfile.CourtesyName || '').trim()) {
                                charToUpdate.CourtesyName = detailedNpcProfile.CourtesyName.trim();
                            }

                            if (detailedNpcProfile.level !== charToUpdate.level) {
                                charToUpdate.level = detailedNpcProfile.level;
                                charToUpdate.baseHp = 200 + (charToUpdate.level - 1) * 20;
                                charToUpdate.baseAtk = 20 + (charToUpdate.level - 1) * 2;
                                charToUpdate.baseDef = 10 + (charToUpdate.level - 1) * 1;
                                charToUpdate.baseSpd = 30 + (charToUpdate.level - 1) * 1;
                                charToUpdate.ap = calculateTotalAP(charToUpdate.level);
                                charToUpdate = autoAllocateNpcAp(charToUpdate);
                            }
                            charToUpdate.description = ""; 
                            charToUpdate.isAppraised = true;
                        }

                        if (generatedSkill) {
                            if (!charToUpdate.skills) charToUpdate.skills = [];
                            charToUpdate.skills.push(generatedSkill);

                            if (!charToUpdate.learnedSkills) charToUpdate.learnedSkills = [];

                            if (!charToUpdate.equippedSkills) {
                                charToUpdate.equippedSkills = {
                                    combat_basic_1: null,
                                    combat_basic_2: null,
                                    combat_basic_3: null,
                                    combat_basic_4: null,
                                    combat_basic_5: null,
                                    combat_basic_6: null,
                                    combat_basic_7: null,
                                    combat_basic_8: null,
                                    combat_ultimate: null,
                                    adventure_1: null,
                                    adventure_2: null,
                                    adventure_3: null
                                };
                            }

                            if (generatedSkill.skillCategory === 'ultimate') {
                                if (!charToUpdate.equippedSkills.combat_ultimate) {
                                    charToUpdate.equippedSkills.combat_ultimate = generatedSkill;
                                } else {
                                    charToUpdate.learnedSkills.push(generatedSkill);
                                }
                            } else {
                                const basicSlot = COMBAT_BASIC_SKILL_SLOTS.find(slot => !charToUpdate.equippedSkills[slot]);
                                if (basicSlot) {
                                    charToUpdate.equippedSkills[basicSlot] = generatedSkill;
                                } else {
                                    charToUpdate.learnedSkills.push(generatedSkill);
                                }
                            }
                        }

                        newKnowledge.characters[charIndex] = calculateFinalStats(charToUpdate, newKnowledge.characters);
                    }
                    return newKnowledge;
                });

                setTimeout(() => {
                    let contentMsg = "Đã cập nhật thông tin chi tiết cho đồng hành [" + npc.Name + "].";
                    if (generatedSkill) {
                        contentMsg += " Đồng thời lĩnh ngộ kỹ năng chiến đấu mới: [" + generatedSkill.Name + "].";
                    }
                    setModalMessage({ 
                        show: true, 
                        title: "Đồng Hành Hoàn Thiện", 
                        content: contentMsg, 
                        type: "success" 
                    });
                }, 100);

            } catch (error) {
                console.error("Lỗi tự động thiết lập đồng hành ngầm:", error);
                autoAppraisedRefs.current.delete(npc.id);
            }
        };

        setupCompanion();
    }
}, [knowledge.characters, isProcessingAction, isLoading, apiMode, apiKey, gameSettings]);

// Tự động "Giám Định Tiểu Sử" cho NPC thường (không phải Companion) NGAY KHI cốt truyện đánh dấu họ có
// trọng số quan hệ với nhân vật chính (đã xuất hiện trong knowledge.relationships qua thẻ [RELATIONSHIP_CHANGED]) —
// tránh tốn thêm 1 lượt gọi AI cho MỌI NPC nền/lướt qua, chỉ áp dụng cho NPC câu chuyện thực sự quan tâm tới.
useEffect(() => {
    if (isProcessingAction || isLoading) return;

    const relationshipNpcNames = new Set((knowledge.relationships || []).map(r => r.NPC));

    const npcsInNeed = knowledge.characters.filter(c =>
        !c.isPlayer &&
        !c.isCompanion &&
        !c.isPermanentlyDead &&
        !c.isAppraised &&
        relationshipNpcNames.has(c.Name) &&
        !autoAppraisedRefs.current.has(c.id)
    );

    if (npcsInNeed.length > 0) {
        const npc = npcsInNeed[0];
        autoAppraisedRefs.current.add(npc.id);

        const autoAppraiseStoryNpc = async () => {
            try {
                const effectiveApiKey = apiMode === 'userKey' ? apiKey : "";
                if (apiMode === 'userKey' && !effectiveApiKey) return;

                const playerLvl = knowledge.characters.find(c => c.isPlayer)?.level || 1;
                const detailedNpcProfile = await fetchNpcDetailsFromAI(npc, gameSettings, effectiveApiKey, playerLvl);
                if (!detailedNpcProfile) return;

                setknowledge(prev => {
                    const newKnowledge = JSON.parse(JSON.stringify(prev));
                    const charIndex = newKnowledge.characters.findIndex(c => c.id === npc.id);
                    if (charIndex === -1) return prev;

                    let charToUpdate = newKnowledge.characters[charIndex];
                    charToUpdate.Role = detailedNpcProfile.Role;
                    charToUpdate.Appearance = detailedNpcProfile.Appearance;
                    charToUpdate.Backstory = detailedNpcProfile.Backstory;
                    charToUpdate.Personality = detailedNpcProfile.Personality;
                    charToUpdate.Stance = detailedNpcProfile.Stance;
                    if (String(detailedNpcProfile.CourtesyName || '').trim()) {
                        charToUpdate.CourtesyName = detailedNpcProfile.CourtesyName.trim();
                    }

                    // Chỉ áp Hảo Cảm khởi điểm do AI đánh giá nếu NPC chưa từng có biến động hảo cảm thực tế (vẫn đang ở mức mặc định 0)
                    if ((charToUpdate.affinity ?? 0) === 0 && typeof detailedNpcProfile.Affinity === 'number') {
                        charToUpdate.affinity = Math.max(-100, Math.min(100, Math.round(detailedNpcProfile.Affinity)));
                    }

                    if (detailedNpcProfile.level !== charToUpdate.level) {
                        charToUpdate.level = detailedNpcProfile.level;
                        charToUpdate.baseHp = 200 + (charToUpdate.level - 1) * 20;
                        charToUpdate.baseAtk = 20 + (charToUpdate.level - 1) * 2;
                        charToUpdate.baseDef = 10 + (charToUpdate.level - 1) * 1;
                        charToUpdate.baseSpd = 30 + (charToUpdate.level - 1) * 1;
                        charToUpdate.ap = calculateTotalAP(charToUpdate.level);
                        charToUpdate = autoAllocateNpcAp(charToUpdate);
                    }

                    charToUpdate.description = "";
                    charToUpdate.isAppraised = true;

                    newKnowledge.characters[charIndex] = calculateFinalStats(charToUpdate, newKnowledge.characters);
                    return newKnowledge;
                });
            } catch (error) {
                console.error(`Lỗi tự động giám định NPC câu chuyện "${npc.Name}":`, error);
                autoAppraisedRefs.current.delete(npc.id);
            }
        };

        autoAppraiseStoryNpc();
    }
}, [knowledge.characters, knowledge.relationships, isProcessingAction, isLoading, apiMode, apiKey, gameSettings]);


useEffect(() => {
    // Chỉ thực thi khi có dữ liệu khởi tạo combat và chưa có combat loop nào đang chạy
    if (combatInitializationData && !activeCombatLoop) {
        const { playerParty, enemies, combatType } = combatInitializationData;

        let finalStatCombatants = [];
        if (combatType === 'PvP') {
            finalStatCombatants = [...playerParty, ...enemies].map(c => ({
                ...c,
                skills: c.skills || [],
            }));
        } else {
            const allCombatantsInvolved = [...playerParty, ...enemies].map(c => ({
                ...c,
                skills: c.skills || [],
            }));
            finalStatCombatants = allCombatantsInvolved.map(c => calculateFinalStats(c));
        }

        // KHỞI TẠO ĐÚNG THỨ TỰ THAM SỐ
        const loop = new CombatLoop(
            finalStatCombatants,        // 1. combatants
            handleCombatStateChange,    // 2. onStateChange
            handleActionRequest,        // 3. onActionRequest
            handleCombatEnd,            // 4. onCombatEnd
            combatType,                 // 5. combatType
            knowledge.sharedCooldowns,  // 6. sharedCooldowns
            // 7. onAnimateAction — Combat System (design/gdd/combat-system.md): không còn UI/animation trực quan
            // nữa (không VisualCombatArena), nên đây chỉ là no-op resolve ngay lập tức để CombatLoop không bị
            // chặn chờ một tín hiệu hoạt ảnh không còn tồn tại.
            async () => {},

            // 8. onPvPActionGenerated
            async (pvpPayload) => {
                if (pvpRoomRef.current) {
                    const roomRef = doc(pvpDb, `pvp_rooms/${pvpRoomRef.current.id}`);
                    await updateDoc(roomRef, {
                        'turn_state.action_id': crypto.randomUUID(),
                        'turn_state.sender': pvpRoomRef.current.role,
                        'turn_state.payload': pvpPayload
                    });
                }
            },
            callCombatAI 
        );

        setActiveCombatLoop(loop);
        setTimeout(() => {
            loop.start();
        }, 100);

        setCombatInitializationData(null);
    }
  }, [combatInitializationData]); 

const calculateSimpleChecksum = (str) => {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        const char = str.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash;
    }
    return Math.abs(hash).toString(36);
};

const handleSaveGame = async (includeImages = true) => {
   if (!storyHistory || storyHistory.length === 0) {
       setModalMessage({ show: true, title: 'Không Thể Lưu', content: 'Chưa có diễn biến nào để lưu lại.', type: 'info' });
       return;
   }

   if (gameMode !== 'EXPLORATION') {
       setModalMessage({ 
           show: true, 
           title: 'Chưa Thể Xuất Tệp', 
           content: 'Không thể xuất tệp lưu trữ ngoại tuyến khi đang trong trận chiến hoặc đang giao dịch. Hãy kết thúc sự việc hiện tại trước!', 
           type: 'info' 
       });
       return;
   }

   const isSystemIdle = !isLoading && !isProcessingAction && (!knowledge.pendingCreations || knowledge.pendingCreations.length === 0);
   if (!isSystemIdle) {
       setModalMessage({ 
           show: true, 
           title: 'Chưa Thể Lưu', 
           content: 'Thiên Đạo đang bận diễn hóa hoặc còn vật phẩm đang chờ giám định trong hàng chờ. Vui lòng đợi lượt chơi kết thúc hoàn toàn trước khi lưu tệp ngoại tuyến!', 
           type: 'info' 
       });
       return;
   }


   let knowledgeToSave = JSON.parse(JSON.stringify(knowledge));
        if (knowledgeToSave.pendingModeChange) delete knowledgeToSave.pendingModeChange;

        if (knowledgeToSave.htab) {
            knowledgeToSave.htab.avatarBase64 = null;
        }
        if (knowledgeToSave.systemAssistant) {
            knowledgeToSave.systemAssistant.images = { base: null, idle: null, smile: null, sad: null, angry: null, laugh: null };
        }

   if (includeImages) {
       setModalMessage({ show: true, title: 'Đang Đóng Gói...', content: 'Đang lấy dữ liệu hình ảnh từ bộ nhớ trình duyệt để xuất file (Việc này có thể mất vài giây)...', type: 'info' });
       try {
           await Promise.all(knowledgeToSave.characters.map(async (char) => {
               if (char.avatarStoredLocally && char.id) {
                   const base64 = await getAvatarFromIndexedDB(char.id);
                   if (base64) char.avatarBase64 = base64; 
               }
           }));
       } catch (e) {
           console.error("Lỗi khi đóng gói ảnh:", e);
       }
   } else {
       knowledgeToSave.characters.forEach(char => {
           char.avatarBase64 = null;
           if (char.images) {
               char.images = { base: null, idle: null, attack_normal: null, skills: {} };
           }
       });
   }

   const saveData = {
       id: currentGameId, 
       currentTurn: currentTurn,
       saveVersion: "2.8",
       timestamp: new Date().toISOString(),
       gameSettings,
       knowledge: knowledgeToSave, 
       storyHistory: storyHistory, 
       choices: choices,
       gameMode: gameMode,
       activeTrade: activeTrade, 
       storySummaries: storySummaries,
       borderVersion: "1.0",
       adventureTurnCount: adventureTurnCount,
   };

   try {
       const orderedSaveData = putLongAttributesLast(saveData);
       let finalFileContent = "";
       const difficulty = gameSettings.difficulty || 'Thường';
       const isSecureMode = difficulty === 'Khó' || difficulty === 'Ác Mộng';

       if (isSecureMode) {
           const rawJson = JSON.stringify(orderedSaveData);
           const compressed = window.LZString ? window.LZString.compressToUTF16(rawJson) : rawJson;
           const base64Payload = btoa(unescape(encodeURIComponent(compressed)));
           const charCount = base64Payload.length;
           const checksum = calculateSimpleChecksum(base64Payload + charCount);

           finalFileContent = JSON.stringify({
               secure: true,
               data: base64Payload,
               length: charCount,
               checksum: checksum
           }, null, 2);
       } else {
           finalFileContent = JSON.stringify(orderedSaveData, null, 2);
       }

       const blob = new Blob([finalFileContent], { type: 'application/json' });
       const url = URL.createObjectURL(blob);
       const a = document.createElement('a');
       
       const now = new Date();
       const yyyy = now.getFullYear();
       const mm = String(now.getMonth() + 1).padStart(2, '0');
       const dd = String(now.getDate()).padStart(2, '0');
       const hh = String(now.getHours()).padStart(2, '0');
       const min = String(now.getMinutes()).padStart(2, '0');
       const cleanTimestamp = `${dd}-${mm}-${yyyy}_${hh}h${min}`;

       const cleanStr = (str) => {
           if (!str) return 'Story';
           return str
               .normalize('NFD')
               .replace(/[\u0300-\u036f]/g, '')
               .replace(/đ/g, 'd')
               .replace(/Đ/g, 'D')
               .replace(/[^a-zA-Z0-9]/g, '_')
               .replace(/_+/g, '_')
               .replace(/^_+|_+$/g, '');
       };

       const safeStoryTitle = cleanStr(gameSettings.storyTitle);
       const safeCharName = cleanStr(gameSettings.characterName);
       const suffix = isSecureMode ? "SECURE" : (includeImages ? "FULL" : "LITE");
       
       a.href = url;
       a.download = `PhieuLuu_${safeStoryTitle}_${safeCharName}_${cleanTimestamp}_${suffix}.json`;
       
       document.body.appendChild(a);
       a.click();
       document.body.removeChild(a);
       URL.revokeObjectURL(url);
       
       setModalMessage({ 
           show: true, 
           title: 'Xuất Tệp Thành Công', 
           content: isSecureMode 
               ? 'Đã mã hóa nén chữ ký và tải tệp bảo mật về thiết bị.' 
               : 'Đã xuất tệp thành công. Nếu muốn tiếp tục chơi sau khi thoát, hãy chọn nhập tệp.', 
           type: 'success' 
        });
   } catch (error) {
       console.error("Lỗi khi tạo tệp tải về:", error);
       setModalMessage({ show: true, title: 'Lỗi Xuất tệp', content: error.message, type: 'error' });
   }
};

// Đóng gói đúng dữ liệu save (kèm ảnh nhân vật, để mở lại đầy đủ trên bất kỳ thiết bị nào) — tái dùng
// đúng cấu trúc/logic đóng gói ảnh của handleSaveGame để đảm bảo dữ liệu tương thích với loadGameAndResetHistory.
const buildGithubSaveDataObject = async () => {
    let knowledgeToSave = JSON.parse(JSON.stringify(knowledge));
    if (knowledgeToSave.pendingModeChange) delete knowledgeToSave.pendingModeChange;
    if (knowledgeToSave.htab) knowledgeToSave.htab.avatarBase64 = null;
    if (knowledgeToSave.systemAssistant) {
        knowledgeToSave.systemAssistant.images = { base: null, idle: null, smile: null, sad: null, angry: null, laugh: null };
    }

    await Promise.all(knowledgeToSave.characters.map(async (char) => {
        if (char.avatarStoredLocally && char.id) {
            const base64 = await getAvatarFromIndexedDB(char.id);
            if (base64) char.avatarBase64 = base64;
        }
    }));

    return {
        id: currentGameId,
        currentTurn,
        saveVersion: "2.8",
        timestamp: new Date().toISOString(),
        gameSettings,
        knowledge: knowledgeToSave,
        storyHistory,
        choices,
        gameMode,
        activeTrade,
        storySummaries,
        adventureTurnCount,
    };
};

const handleOpenGithubSaveModal = () => {
    if (!GITHUB_SAVE_TOKEN) {
        setModalMessage({ show: true, title: 'Chưa Cấu Hình GitHub', content: 'Chưa thiết lập VITE_GITHUB_TOKEN trong .env.local. Vui lòng tạo Personal Access Token (quyền "Contents: Read and write" cho repo lưu trữ) rồi điền vào .env.local và khởi động lại ứng dụng.', type: 'error' });
        return;
    }
    if (!storyHistory || storyHistory.length === 0) {
        setModalMessage({ show: true, title: 'Không Thể Lưu', content: 'Chưa có diễn biến nào để lưu lại.', type: 'info' });
        return;
    }
    if (gameMode !== 'EXPLORATION') {
        setModalMessage({ show: true, title: 'Chưa Thể Lưu', content: 'Không thể lưu khi đang trong trận chiến hoặc đang giao dịch. Hãy kết thúc sự việc hiện tại trước!', type: 'info' });
        return;
    }
    const isSystemIdle = !isLoading && !isProcessingAction && (!knowledge.pendingCreations || knowledge.pendingCreations.length === 0);
    if (!isSystemIdle) {
        setModalMessage({ show: true, title: 'Chưa Thể Lưu', content: 'Thiên Đạo đang bận diễn hóa hoặc còn vật phẩm đang chờ giám định trong hàng chờ. Vui lòng đợi lượt chơi kết thúc hoàn toàn trước khi lưu!', type: 'info' });
        return;
    }
    setShowGithubSaveSlotModal(true);
};

const handleConfirmGithubSaveSlot = async (slotNumber) => {
    setShowGithubSaveSlotModal(false);
    if (isGithubSaveBusy) return;
    setIsGithubSaveBusy(true);
    setModalMessage({ show: true, title: 'Đang Lưu Lên GitHub...', content: 'Đang đóng gói và tải dữ liệu lên kho lưu trữ. Vui lòng không đóng trình duyệt...', type: 'info' });

    try {
        // plan.md C-2: GitHub is a best-effort MIRROR. The local checkpoint is
        // written first, with the reason that never gates a turn.
        try {
            await runSystemsCheckpoint('manual_backup', null, currentTurn);
        } catch (mirrorError) {
            console.error('[systems] manual_backup checkpoint:', mirrorError);
        }
        const saveDataObject = await buildGithubSaveDataObject();
        const slotPath = `${GITHUB_SAVES_DIR}/slot_${slotNumber}.json`;

        // Lấy sha hiện tại của file slot (nếu đã tồn tại) để cập nhật đúng cách, tránh lỗi 409 conflict.
        const existingSlotFile = await getGithubJsonFile(slotPath);
        await putGithubJsonFile(
            slotPath,
            saveDataObject,
            `Lưu game: ${gameSettings.characterName || 'Vô Danh'} - Lượt ${currentTurn} (${new Date().toLocaleString('vi-VN')})`,
            existingSlotFile?.sha
        );

        // Cập nhật bảng chỉ mục 5 slot.
        const { slots, sha: indexSha } = await getGithubSaveIndex();
        slots[slotNumber - 1] = {
            gameId: currentGameId,
            timestamp: saveDataObject.timestamp,
            characterName: gameSettings.characterName || 'Vô Danh',
            storyTitle: gameSettings.storyTitle || 'Thế giới vô danh',
            difficulty: gameSettings.difficulty || 'Thường',
            currentTurn,
        };
        await putGithubJsonFile(
            GITHUB_INDEX_PATH,
            { slots },
            `Cập nhật chỉ mục lưu trữ - Slot ${slotNumber}`,
            indexSha
        );

        setModalMessage({ show: true, title: 'Đã Lưu Thành Công', content: `Đã lưu tiến trình lên GitHub (Phiến Ngọc ${slotNumber}). Bạn có thể tải lại đúng ván này trên bất kỳ thiết bị nào khác.`, type: 'success' });
    } catch (error) {
        console.error("Lỗi khi lưu lên GitHub:", error);
        setModalMessage({ show: true, title: 'Lỗi Lưu GitHub', content: error.message, type: 'error' });
    } finally {
        setIsGithubSaveBusy(false);
    }
};

const handleClearImageCache = async () => {
    setConfirmationModal({
        show: true,
        title: 'Xóa Dữ Liệu Ảnh?',
        content: 'Hành động này sẽ xóa toàn bộ ảnh nhân vật được lưu trong trình duyệt này để giải phóng dung lượng.\n\nNhân vật vẫn còn, nhưng ảnh sẽ biến mất cho đến khi bạn tải lại tệp game có chứa ảnh (bản Full). Bạn có chắc không?',
        onConfirm: async () => {
            try {
                // Gọi hàm xóa IndexedDB
                const db = await openDB();
                const tx = db.transaction(STORE_NAME_AVATARS, 'readwrite');
                const store = tx.objectStore(STORE_NAME_AVATARS);
                const request = store.clear(); // Xóa sạch

                request.onsuccess = () => {
                    // Cập nhật lại state để giao diện biết là mất ảnh rồi
                    setknowledge(prev => {
                        const newK = JSON.parse(JSON.stringify(prev));
                        newK.characters.forEach(c => {
                            c.avatarStoredLocally = false;
                            c.avatarUrl = null;
                            c.avatarBase64 = null;
                        });
                        return newK;
                    });
                    setModalMessage({ show: true, title: 'Đã Dọn Dẹp', content: 'Đã xóa toàn bộ ảnh trong bộ nhớ trình duyệt.', type: 'success' });
                };
            } catch (e) {
                setModalMessage({ show: true, title: 'Lỗi', content: 'Không thể xóa cache: ' + e.message, type: 'error' });
            }
        },
        confirmText: 'Xóa Sạch Ảnh',
        cancelText: 'Hủy'
    });
};

const handleDeleteNpc = (npcId) => {
    setknowledge(prev => {
        const npcToDelete = prev.characters.find(c => c.id === npcId);
        if (!npcToDelete) return prev;

        const newKnowledge = JSON.parse(JSON.stringify(prev));
        newKnowledge.characters = newKnowledge.characters.filter(c => c.id !== npcId);
        
        // Cũng xóa khỏi lore nếu có
        if (newKnowledge.loreNpcs) {
            newKnowledge.loreNpcs = newKnowledge.loreNpcs.filter(lore => lore.name !== npcToDelete.Name);
        }

        setModalMessage({ show: true, title: 'Đã Xóa', content: `Đã xóa vĩnh viễn NPC "${npcToDelete.Name}" khỏi thế giới.`, type: 'success' });
        return newKnowledge;
    });
};

const handleCreateNpc = async (npcData, options = {}) => {
    if (!npcData.name || !npcData.description) {
        setModalMessage({ show: true, title: 'Thiếu Thông Tin', content: 'Vui lòng nhập đầy đủ tên và mô tả cho NPC.', type: 'error' });
        return;
    }

    setIsProcessingAction(true);
    setModalMessage({ show: true, title: 'Đang Nặn Người...', content: `AI đang tạo ra NPC "${npcData.name}"...`, type: 'info' });

    const effectiveApiKey = apiMode === 'userKey' ? apiKey : "";
    if (apiMode === 'userKey' && !effectiveApiKey) {
        setModalMessage({ show: true, title: 'Lỗi API Key', content: 'Vui lòng cấu hình API Key.', type: 'error' });
        setIsProcessingAction(false);
        return;
    }

    const playerLevel = knowledge.characters.find(c => c.isPlayer)?.level || 1;

    const prompt = `
        VAI TRÒ: Bạn là một nhà thiết kế nhân vật game.
        BỐI CẢNH: 
        - Thế giới game: "${gameSettings.theme}"
        - Cấp độ của người chơi hiện tại: ${playerLevel}

        YÊU CẦU: Dựa vào thông tin người dùng cung cấp dưới đây, hãy tạo ra một đối tượng NPC hoàn chỉnh.
        - Tên: "${npcData.name}"
        - Mô tả: "${npcData.description}"

        NHIỆM VỤ:
        1.  **Sáng tạo:** Dựa vào mô tả, hãy tự suy luận ra các thuộc tính sau cho NPC: 'level' (gần bằng hoặc thấp hơn cấp người chơi), 'Stance' (Thái độ ban đầu), 'Personality' (Tính cách), 'Gender' (Giới tính: Nam, Nữ, Khác), và 'sizeCategory' (Chiều cao: 1:dáng người nhỏ nhắn, 2:dáng người trung bình, kích cỡ vừa phải, 3:dáng cao ráo, kích cỡ khá lớn, 4:dáng to cao vạm vỡ, 5:khồng lồ, cực kỳ lớn).
        2.  **Tên tự ('CourtesyName'):** CHỈ phần tự, KHÔNG kèm họ (VD: Quan Vũ tự "Vân Trường", Thái Diễm tự "Văn Cơ"). ${gameSettings.isTamQuocWorld
            ? `ĐÂY LÀ THẾ GIỚI TAM QUỐC nên trường này BẮT BUỘC có giá trị: nhân vật lịch sử/danh nhân dùng ĐÚNG tự trong sử sách; nhân vật hư cấu thì ngươi PHẢI TỰ NGHĨ một tên tự Hán Việt phù hợp thân phận và họ tên.`
            : `Nếu bối cảnh cổ trang Á Đông (Võ Hiệp/Tiên Hiệp/Huyền Huyễn cổ đại — không riêng gì Tam Quốc) VÀ nhân vật thuộc tầng lớp có học thức/danh môn/quý tộc (tiểu thư, công tử, thế gia vọng tộc, đệ tử môn phái lớn...), trường này BẮT BUỘC có giá trị — ngươi PHẢI TỰ NGHĨ một tên tự Hán Việt 1-2 chữ phù hợp thân phận và họ tên, TUYỆT ĐỐI KHÔNG bỏ trống chỉ vì lưỡng lự có phù hợp hay không. CHỈ trả về chuỗi rỗng "" khi bối cảnh KHÔNG phải cổ trang Á Đông, hoặc nhân vật rõ ràng xuất thân bình dân/không có học thức.`}
        3.  **Định dạng:** Chỉ trả về một đối tượng JSON duy nhất chứa các thuộc tính: level, Stance, Personality, Gender, sizeCategory, CourtesyName.
    `;

    const schema = {
        type: "OBJECT",
        properties: {
            level: { type: "NUMBER" },
            Stance: { type: "STRING", enum: ["Thân thiện", "Thù địch", "Trung lập", "Sợ hãi", "Nghi ngờ"] },
            Personality: { type: "STRING" },
            Gender: { type: "STRING", enum: ["Nam", "Nữ", "Khác", "Không xác định"] },
            sizeCategory: { type: "NUMBER" },
            CourtesyName: { type: "STRING" }
        },
        required: ["level", "Stance", "Personality", "Gender", "sizeCategory", "CourtesyName"]
    };
    
    const payload = {
        contents: [{ role: "user", parts: [{ text: prompt }] }],
        generationConfig: { response_mime_type: "application/json", response_schema: schema }
    };
    const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_TEXT_MODEL_FALLBACKS[0]}:generateContent?key=${effectiveApiKey}`;

    try {
        const jsonText = await fetchWithRetries(apiUrl, payload);
        const aiData = JSON.parse(jsonText);

        setknowledge(prev => {
            const newKnowledge = JSON.parse(JSON.stringify(prev));
            
            let newNpc = {
                ...INITIAL_STATS,
                id: crypto.randomUUID(),
                isPlayer: false,
                isCompanion: false,
                affinity: 0, // Hảo cảm mặc định (người lạ) của NPC dành cho nhân vật chính — thang điểm -100 (thù địch) đến 100 (thân thiết)
                Name: npcData.name,
                description: npcData.description,
                ...aiData
            };
            // Tên tự rỗng (thế giới không dùng tự) thì bỏ hẳn trường này khỏi thẻ nhân vật.
            if (!String(newNpc.CourtesyName || '').trim()) delete newNpc.CourtesyName;
            else newNpc.CourtesyName = newNpc.CourtesyName.trim();

            newNpc.baseHp = 200 + (newNpc.level - 1) * 20;
            newNpc.baseAtk = 20 + (newNpc.level - 1) * 2;
            newNpc.baseDef = 10 + (newNpc.level - 1) * 1;
            newNpc.baseSpd = 30 + (newNpc.level - 1) * 1;
            
            const totalApShouldHave = calculateTotalAP(newNpc.level);
            newNpc.ap = totalApShouldHave;
            
            // Tự động phân bổ AP theo hệ thống
            if (newNpc.ap > 0) {
                newNpc = autoAllocateNpcAp(newNpc);
            }
            
            // Sau khi đã có Base Stat và Allocated Points, mới tiến hành tính toán Form cuối cùng
            const finalNpc = calculateFinalStats(newNpc);

            if (options.fromLore) {
                const createdNameLower = (finalNpc.Name || '').trim().toLowerCase();
                newKnowledge.loreNpcs = (newKnowledge.loreNpcs || []).filter(lore => {
                    if (!lore) return false;
                    if (options.loreId && lore.id === options.loreId) return false;
                    return (lore.Name || lore.name || '').trim().toLowerCase() !== createdNameLower;
                });
                const currentPlayer = newKnowledge.characters.find(c => c.isPlayer);
                if (currentPlayer && currentPlayer.current_location_id) {
                    finalNpc.current_location_id = currentPlayer.current_location_id;
                }
            }

            newKnowledge.characters.push(finalNpc);

            setModalMessage({
                show: true,
                title: options.fromLore ? 'Hiện Thực Hóa Thành Công' : 'Tạo Thành Công',
                content: options.fromLore
                    ? `"${finalNpc.Name}" đã được hiện thực hóa từ tin đồn thành nhân vật thật.`
                    : `NPC "${finalNpc.Name}" đã được thêm vào thế giới.`,
                type: 'success'
            });
            return newKnowledge;
        });

    } catch (error) {
        console.error("Lỗi khi tạo NPC:", error);
        setModalMessage({ show: true, title: 'Lỗi AI', content: `Không thể tạo NPC: ${error.message}`, type: 'error' });
    } finally {
        setIsProcessingAction(false);
    }
};

const handleManifestLoreNpc = async (loreNpc) => {
    if (!loreNpc) return;
    const name = loreNpc.Name || loreNpc.name;
    if (!name) return;
    await handleCreateNpc(
        { name, description: loreNpc.description || `Nhân vật được đồn đại với tên ${name}.` },
        { fromLore: true, loreId: loreNpc.id }
    );
};


const handleRenameNpc = useCallback((npcId, newName, newDescription) => {
    if (!newName || !newName.trim()) {
        setModalMessage({ show: true, title: "Lỗi", content: "Tên NPC không được để trống.", type: "error" });
        return;
    }

    setknowledge(prev => {
        const newKnowledge = JSON.parse(JSON.stringify(prev));
        const charIndex = newKnowledge.characters.findIndex(c => c.id === npcId);

        if (charIndex > -1) {
            const oldName = newKnowledge.characters[charIndex].Name;
            newKnowledge.characters[charIndex].Name = newName.trim();
            if (newDescription !== undefined) {
                newKnowledge.characters[charIndex].description = newDescription.trim();
            }
            setModalMessage({ show: true, title: "Cập Nhật Thành Công", content: `Đã đổi tên NPC "${oldName}" thành "${newName.trim()}".`, type: "success" });
        }
        return newKnowledge;
    });
}, [setModalMessage]);

// Cho phép người chơi tự điền/sửa Tự (tên chữ) trực tiếp từ bảng thông tin nhân
// vật (QuickLoreModal) — bù lại những trường hợp AI bỏ sót Tự cho NPC danh môn
// dù đáng lẽ phải có (xem quy tắc CourtesyName trong prompt). Chuỗi rỗng xóa Tự.
const handleSetCourtesyName = useCallback((characterId, newCourtesyName) => {
    const trimmed = (newCourtesyName || '').trim();
    setknowledge(prev => {
        const charIndex = prev.characters.findIndex(c => c.id === characterId);
        if (charIndex === -1) return prev;
        const newCharacters = prev.characters.slice();
        const updatedChar = { ...newCharacters[charIndex] };
        if (trimmed) updatedChar.CourtesyName = trimmed;
        else delete updatedChar.CourtesyName;
        newCharacters[charIndex] = updatedChar;
        return { ...prev, characters: newCharacters };
    });
}, [setknowledge]);

// Nút "+ Thêm Tự" trong bảng thông tin: để AI tự nghĩ (khác với "(sửa)" ở trên,
// nơi người chơi tự gõ tay). Dùng isProcessingAction làm cờ khóa/loading — cùng
// pattern handleAppraiseNpc đã dùng cho một tác vụ AI nền tương tự.
const handleGenerateCourtesyName = async (npcId) => {
    const npc = knowledge.characters.find(c => c.id === npcId);
    if (!npc) return;

    // Có sẵn Tự rồi thì đây là "Đổi lại" (yêu cầu AI nghĩ tên KHÁC, xem
    // excludeCourtesyName trong fetchCourtesyNameFromAI); chưa có thì là "Thêm".
    const isRerolling = !!npc.CourtesyName;

    setIsProcessingAction(true);
    setModalMessage({ show: true, title: 'Đang Suy Nghĩ...', content: `Đang tra cứu điển tích để ${isRerolling ? 'đổi sang một Tự khác' : 'đặt Tự phù hợp'} cho [${npc.Name}]...`, type: 'info' });

    try {
        const effectiveApiKey = apiMode === 'userKey' ? apiKey : "";
        if (apiMode === 'userKey' && !effectiveApiKey) throw new Error("API Key chưa được cấu hình.");

        const courtesyName = await fetchCourtesyNameFromAI(npc, gameSettings, effectiveApiKey, npc.CourtesyName);
        if (!courtesyName) throw new Error("AI không thể nghĩ ra tên tự phù hợp lúc này.");

        handleSetCourtesyName(npcId, courtesyName);
        setModalMessage({ show: true, title: 'Thành Công', content: `Đã ${isRerolling ? 'đổi' : 'đặt'} Tự "${courtesyName}" cho [${npc.Name}].`, type: 'success' });
    } catch (error) {
        setModalMessage({ show: true, title: 'Lỗi', content: error.message || 'Không thể tạo Tự lúc này.', type: 'error' });
    } finally {
        setIsProcessingAction(false);
    }
};

const handleLoadSetupFromFile = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const loadedData = JSON.parse(e.target.result);
            // Kiểm tra xem tệp có đúng định dạng không
            if (!loadedData.setupVersion || !loadedData.settings) {
                throw new Error("Tệp không phải là tệp lưu thiết lập hợp lệ.");
            }

            // Cập nhật lại toàn bộ gameSettings
            setGameSettings(loadedData.settings);

            setModalMessage({ show: true, title: 'Thành Công', content: 'Đã tải thiết lập thành công!', type: 'success' });
        } catch (error) {
            console.error("Lỗi khi tải tệp thiết lập:", error);
            setModalMessage({ show: true, title: 'Lỗi Tải Tệp', content: `Không thể đọc tệp thiết lập: ${error.message}`, type: 'error' });
        }
    };
    reader.readAsText(file);
    // Reset giá trị của input để có thể chọn lại cùng một tệp
    event.target.value = null;
};

const handleDeleteLocation = (locationId) => {
    setknowledge(prev => {
        const locationToDelete = prev.locations.find(loc => loc.id === locationId);
        if (!locationToDelete) return prev;

        const newKnowledge = JSON.parse(JSON.stringify(prev));
        newKnowledge.locations = newKnowledge.locations.filter(loc => loc.id !== locationId);

        if (newKnowledge.loreLocations) {
            newKnowledge.loreLocations = newKnowledge.loreLocations.filter(lore => lore.name !== locationToDelete.Name);
        }

        setModalMessage({ show: true, title: 'Đã Xóa', content: `Đã xóa vĩnh viễn địa điểm "${locationToDelete.Name}" khỏi thế giới.`, type: 'success' });
        return newKnowledge;
    });
};

const handleUpdateLocation = (locationId, newName, newDescription, newTier, newParentId) => {
    if (!newName || !newName.trim()) {
        setModalMessage({ show: true, title: "Lỗi", content: "Tên địa điểm không được để trống.", type: "error" });
        return;
    }
    
    if (newTier > 1 && !newParentId) {
        setModalMessage({ show: true, title: "Lỗi Phả Hệ", content: "Địa điểm từ Loại 2 trở xuống phải có một Địa điểm Mẹ.", type: "error" });
        return;
    }

    setknowledge(prev => {
        const newKnowledge = JSON.parse(JSON.stringify(prev));
        const locIndex = newKnowledge.locations.findIndex(l => l.id === locationId);

        if (locIndex > -1) {
            const oldName = newKnowledge.locations[locIndex].Name;
            newKnowledge.locations[locIndex].Name = newName.trim();
            
            if (newDescription !== undefined) {
                newKnowledge.locations[locIndex].description = newDescription.trim();
            }
            // Cập nhật Cấp bậc và Địa điểm mẹ
            if (newTier !== undefined) {
                newKnowledge.locations[locIndex].tier = newTier;
            }
            if (newParentId !== undefined) {
                newKnowledge.locations[locIndex].parentLocationId = newParentId || null;
            }

            setModalMessage({ show: true, title: "Cập Nhật Thành Công", content: `Đã cập nhật thông tin và vị trí cho "${newName.trim()}".`, type: "success" });
        }
        return newKnowledge;
    });
};

const handleCreateLocation = async (locationData) => {
    if (!locationData.name || !locationData.description) {
        setModalMessage({ show: true, title: 'Thiếu Thông Tin', content: 'Vui lòng nhập đầy đủ tên và mô tả cho địa điểm.', type: 'error' });
        return;
    }

    if (locationData.tier > 1 && !locationData.parentLocationId) {
        setModalMessage({ show: true, title: 'Thiếu Địa Điểm Mẹ', content: 'Các địa điểm từ Loại 2 trở xuống bắt buộc phải chọn một địa điểm Mẹ.', type: 'error' });
        return;
    }

    setIsProcessingAction(true);
    setModalMessage({ show: true, title: 'Đang Kiến Tạo...', content: `AI đang hình thành địa điểm "${locationData.name}"...`, type: 'info' });

    const effectiveApiKey = apiMode === 'userKey' ? apiKey : "";
    if (apiMode === 'userKey' && !effectiveApiKey) {
        setModalMessage({ show: true, title: 'Lỗi API Key', content: 'Vui lòng cấu hình API Key.', type: 'error' });
        setIsProcessingAction(false);
        return;
    }

    const prompt = `
        VAI TRÒ: Bạn là một nhà kiến tạo thế giới game.
        BỐI CẢNH: 
        - Thế giới game: "${gameSettings.theme}"
        YÊU CẦU: Dựa vào thông tin người dùng cung cấp, hãy phân loại địa điểm.
        - Tên: "${locationData.name}"
        - Mô tả: "${locationData.description}"

        NHIỆM VỤ:
        1.  **Phân loại:** Dựa vào mô tả, hãy chọn MỘT 'category' phù hợp nhất cho địa điểm này từ danh sách cho phép.
        2.  **Định dạng:** Chỉ trả về một đối tượng JSON duy nhất chứa thuộc tính 'category'.
        
        DANH SÁCH CATEGORY HỢP LỆ: ["Thành Trì", "Làng Mạc", "Công Trình", "Di Tích Cổ", "Vùng Đất Tự Nhiên", "Cửa Hàng", "Tông Môn", "Lục Địa", "Đại Dương", "Quốc Gia"]
    `;

    const schema = {
        type: "OBJECT",
        properties: {
            category: { type: "STRING", enum: ["Thành Trì", "Làng Mạc", "Công Trình", "Di Tích Cổ", "Vùng Đất Tự Nhiên", "Cửa Hàng", "Tông Môn", "Lục Địa", "Đại Dương", "Quốc Gia"] }
        },
        required: ["category"]
    };
    
    const payload = {
        contents: [{ role: "user", parts: [{ text: prompt }] }],
        generationConfig: { response_mime_type: "application/json", response_schema: schema }
    };
    const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_TEXT_MODEL_FALLBACKS[0]}:generateContent?key=${effectiveApiKey}`;

    try {
        const jsonText = await fetchWithRetries(apiUrl, payload);
        const aiData = JSON.parse(jsonText);

        setknowledge(prev => {
            const newKnowledge = JSON.parse(JSON.stringify(prev));
            const newLocation = {
                id: crypto.randomUUID(),
                Name: locationData.name,
                description: locationData.description,
                category: aiData.category,
                tier: parseInt(locationData.tier, 10) || 1,
                parentLocationId: locationData.parentLocationId || null
            };
            if (!newKnowledge.locations) {
                newKnowledge.locations = [];
            }
            newKnowledge.locations.push(newLocation);
            setModalMessage({ show: true, title: 'Kiến Tạo Thành Công', content: `Địa điểm "${newLocation.Name}" đã được thêm vào thế giới.`, type: 'success' });
            return newKnowledge;
        });

    } catch (error) {
        console.error("Lỗi khi tạo địa điểm:", error);
        setModalMessage({ show: true, title: 'Lỗi AI', content: `Không thể tạo địa điểm: ${error.message}`, type: 'error' });
    } finally {
        setIsProcessingAction(false);
    }
};

const handleLoadGame = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const loadedData = JSON.parse(e.target.result);
            
            if (loadedData && loadedData.secure === true) {
                const base64Payload = loadedData.data || "";
                const lengthVal = loadedData.length || 0;
                const checksumVal = loadedData.checksum || "";

                if (base64Payload.length !== lengthVal) {
                    setModalMessage({ 
                        show: true, 
                        title: 'Phát Hiện Can Thiệp', 
                        content: 'Dung lượng chuỗi mã hóa bị sai lệch so với khai báo ban đầu. Tệp tin đã bị chặn!', 
                        type: 'error' 
                    });
                    return;
                }

                const calculated = calculateSimpleChecksum(base64Payload + lengthVal);
                if (calculated !== checksumVal) {
                    setModalMessage({ 
                        show: true, 
                        title: 'Chữ Ký Không Hợp Lệ', 
                        content: 'Mã kiểm định chữ ký (checksum) bị sai lệch. File savegame đã bị sửa đổi trái phép và không thể nạp tệp!', 
                        type: 'error' 
                    });
                    return;
                }

                const decodedCompressed = decodeURIComponent(escape(atob(base64Payload)));
                const decompressed = window.LZString ? window.LZString.decompressFromUTF16(decodedCompressed) : decodedCompressed;
                const finalData = JSON.parse(decompressed);
                
                loadGameAndResetHistory(finalData);
            } else {
                const difficulty = loadedData?.gameSettings?.difficulty || loadedData?.settings?.difficulty || 'Thường';
                if (difficulty === 'Khó' || difficulty === 'Ác Mộng') {
                    setModalMessage({ 
                        show: true, 
                        title: 'Yêu Cầu Kiểm Định', 
                        content: 'Chế độ Khó và Ác Mộng bắt buộc phải sử dụng tệp tin lưu trữ được nén mã hóa có kèm chữ ký xác thực. Tệp tin chữ thường đã bị từ chối!', 
                        type: 'error' 
                    });
                    return;
                }
                loadGameAndResetHistory(loadedData);
            }
        } catch (error) {
            console.error("Lỗi tải tệp lưu trữ:", error);
            setModalMessage({ show: true, title: 'Lỗi Tải Tệp', content: `Không thể đọc tệp lưu trữ hoặc giải mã thất bại: ${error.message}`, type: 'error' });
        }
    };
    reader.readAsText(file);
    event.target.value = null; 
};
const sanitizeDataForFirestore = (data) => {
    if (data === undefined) return null;
    if (data === null || typeof data !== 'object') return data;
    
    const isPlainObject = (obj) => Object.prototype.toString.call(obj) === '[object Object]';
    const isArray = Array.isArray(data);
    
    if (!isPlainObject(data) && !isArray) {
        return data;
    }
    
    if (isArray) {
        return data
            .map(item => sanitizeDataForFirestore(item))
            .filter(item => item !== undefined);
    }
    
    const sanitizedObject = {};
    for (const key in data) {
        if (Object.prototype.hasOwnProperty.call(data, key)) {
            const value = data[key];
            if (typeof value === 'function') continue;

            const cleanValue = sanitizeDataForFirestore(value);
            if (cleanValue !== undefined) {
                sanitizedObject[key] = cleanValue;
            }
        }
    }
    return sanitizedObject;
};


useEffect(() => {
    if (justExitedCombat) {
        setJustExitedCombat(false); 
        return;
    }

    if (currentTurn > 1 && currentScreen === 'gameplay' && gameMode === 'EXPLORATION') {
        const systemMessages = [];
 
        setknowledge(prev => {
            const newKnowledge = JSON.parse(JSON.stringify(prev));
 
            if (newKnowledge.sharedCooldowns) {
                if (newKnowledge.sharedCooldowns.tactical > 0) {
                    newKnowledge.sharedCooldowns.tactical -= 1;
                }
                if (newKnowledge.sharedCooldowns.potion > 0) {
                    newKnowledge.sharedCooldowns.potion -= 1;
                }
            }
 
            newKnowledge.characters = newKnowledge.characters.map(char => {
                if (char.isPermanentlyDead) return char; // Bỏ qua nhân vật đã chết

                let updatedChar = { ...char };
                const statuses = updatedChar.longTermStatuses || [];
                let isBleeding = false;
                let bleedinghpLoss = 0;
 
                if (updatedChar.isPlayer && updatedChar.skills) {
                    updatedChar.skills = updatedChar.skills.map(skill => ({
                        ...skill,
                        currentCooldown: Math.max(0, (skill.currentCooldown || 0) - 1)
                    }));
                }
 
                if (statuses.length > 0) {
                    updatedChar.longTermStatuses = statuses.map(status => {
                        const template = LONG_TERM_STATUS_TEMPLATES[status.status_id] || status;

                        if (template.effects_per_day?.hp_percent_loss) {
                             isBleeding = true;
                             bleedinghpLoss += (updatedChar.maxhp || 0) * (template.effects_per_day.hp_percent_loss / 100.0);
                        }

                        if (typeof status.duration === 'number' && status.duration > 0) {
                            status.duration -= 1;
                            if (status.duration <= 0) {
                                 systemMessages.push({ type: 'system', content: `**[Hệ thống]** Trạng thái "${status.name}" trên ${updatedChar.Name} đã kết thúc.` });
                                 return null;
                            }
                        }
                        return status;
                    }).filter(Boolean);
                }
 
                if (isBleeding) {
                    updatedChar.hp = Math.max(0, (updatedChar.hp || 0) - Math.floor(bleedinghpLoss));
                    if (bleedinghpLoss > 0) {
                        systemMessages.push({ type: 'system', content: `**[Hệ thống]** ${updatedChar.Name} mất ${Math.floor(bleedinghpLoss)} sinh lực do vết thương.` });
                    }
                }
                
                return updatedChar;
            });
            
            return newKnowledge;
        });
 
        if (systemMessages.length > 0) {
            setStoryHistory(prevHistory => [
                ...prevHistory,
                ...systemMessages.map(msg => ({...msg, id: crypto.randomUUID(), transient: true}))
            ]);
        }
    }
}, [currentTurn, gameMode, justExitedCombat]);




